// FreeLang v8 ML — Phase K 테스트
// FL8 LLM 핵심 모듈: 25개 테스트

import { Interpreter } from "../src/runtime/interpreter";
import { Lexer } from "../src/lexer/lexer";
import { Parser } from "../src/parser/parser";

let passed = 0, failed = 0;

function test(name: string, fn: () => void) {
  try { fn(); console.log(`  ✅ PASS: ${name}`); passed++; }
  catch (e: any) { console.log(`  ❌ FAIL: ${name} — ${e.message}`); failed++; }
}

function expect(actual: any, expected: any, msg = "") {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) throw new Error(`${msg} expected=${JSON.stringify(expected)} got=${JSON.stringify(actual)}`);
}

function expectClose(a: number, b: number, tol = 0.001, msg = "") {
  if (Math.abs(a - b) > tol) throw new Error(`${msg} |${a} - ${b}| > ${tol}`);
}

function runFL8(src: string): any {
  const tokens = new Lexer(src).tokenize().tokens;
  const { program } = new Parser(tokens).parse();
  const interp = new Interpreter();
  return interp.run(program);
}

function runFL8Interp(src: string): Interpreter {
  const tokens = new Lexer(src).tokenize().tokens;
  const { program } = new Parser(tokens).parse();
  const interp = new Interpreter();
  interp.run(program);
  return interp;
}

// ============================================================
// Suite 1: 새 tensor 내장 함수
// ============================================================
console.log("\n── Suite 1: 새 tensor 내장 함수 ──────────────────────────────");

test("t_add: elementwise 덧셈", () => {
  const r = runFL8(`
let a = zeros(2, 3)
let b = ones(2, 3)
let c = t_add(a, b)
tget(c, 0, 0)
`);
  expectClose(r.val, 1.0, 0.001, "t_add");
});

test("t_scale: scalar 곱", () => {
  const r = runFL8(`
let a = ones(2, 2)
let b = t_scale(a, 3.0)
tget(b, 1, 1)
`);
  expectClose(r.val, 3.0, 0.001, "t_scale");
});

test("t_row/t_set_row 왕복", () => {
