// FreeLang v8 ML — Phase K 테스트
// FL8 LLM 핵심 모듈: 25개 테스트

import { Interpreter } from "../src/runtime/interpreter";
import { Lexer } from "../src/lexer/lexer";
import { Parser } from "../src/parser/parser";

let passed = 0, failed = 0;

function test(name: string, fn: () => void) {
  try { fn(); console.log(`  ✅ PASS: ${name}`); passed++; }
  catch (e: any) { console.log(`  ❌ FAIL: ${name} — ${e.message}`); failed++; }
}

function expect(actual: any, expected: any, msg = "") {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) throw new Error(`${msg} expected=${JSON.stringify(expected)} got=${JSON.stringify(actual)}`);
}

function expectClose(a: number, b: number, tol = 0.001, msg = "") {
  if (Math.abs(a - b) > tol) throw new Error(`${msg} |${a} - ${b}| > ${tol}`);
}

function runFL8(src: string): any {
  const tokens = new Lexer(src).tokenize().tokens;
  const { program } = new Parser(tokens).parse();
  const interp = new Interpreter();
  return interp.run(program);
}

function runFL8Interp(src: string): Interpreter {
  const tokens = new Lexer(src).tokenize().tokens;
  const { program } = new Parser(tokens).parse();
  const interp = new Interpreter();
  interp.run(program);
  return interp;
}

// ============================================================
// Suite 1: 새 tensor 내장 함수
// ============================================================
console.log("\n── Suite 1: 새 tensor 내장 함수 ──────────────────────────────");

test("t_add: elementwise 덧셈", () => {
  const r = runFL8(`
let a = zeros(2, 3)
let b = ones(2, 3)
let c = t_add(a, b)
tget(c, 0, 0)
`);
  expectClose(r.val, 1.0, 0.001, "t_add");
});

test("t_scale: scalar 곱", () => {
  const r = runFL8(`
let a = ones(2, 2)
let b = t_scale(a, 3.0)
tget(b, 1, 1)
`);
  expectClose(r.val, 3.0, 0.001, "t_scale");
});

test("t_row/t_set_row 왕복", () => {
  const r = runFL8(`
let t = zeros(3, 4)
let row = ones(4)
let row1 = reshape(row, 4)
t_set_row(t, 1, row1)
let got = t_row(t, 1)
tget(got, 0, 0)
`);
  expectClose(r.val, 1.0, 0.001, "t_row");
});

test("t_softmax: 합=1", () => {
  const r = runFL8(`
let v = randn(8)
let v1 = reshape(v, 8)
let sm = t_softmax(v1)
t_sum(sm)
`);
  expectClose(r.val, 1.0, 0.001, "softmax sum");
});

test("t_layer_norm: 정규화", () => {
  const r = runFL8(`
let x = ones(4)
let x1 = reshape(x, 4)
let s = ones(4)
let s1 = reshape(s, 4)
let b = zeros(4)
let b1 = reshape(b, 4)
let out = t_layer_norm(x1, s1, b1, 0.00001)
t_mean(out)
`);
  expectClose(r.val, 0.0, 0.01, "layer_norm mean≈0");
});

test("t_gelu: 양수 x > 0", () => {
  const r = runFL8(`
let x = ones(4)
let x1 = reshape(x, 4)
let out = t_gelu(x1)
tget(out, 0, 0)
`);
  if (r.val <= 0) throw new Error(`gelu(1) should be > 0, got ${r.val}`);
});

test("t_causal_mask: 대각선 아래=0, 위=-1e9", () => {
  const r = runFL8(`
let m = t_causal_mask(3)
tget(m, 0, 1)
`);
  if (r.val >= -1e8) throw new Error(`causal mask[0,1] should be -1e9, got ${r.val}`);
});

test("t_argmax: 최댓값 인덱스", () => {
  const r = runFL8(`
let v = [0.1, 0.9, 0.3, 0.05]
let t = tensor(v, 4)
t_argmax(t)
`);
  expect(r.val, 1, "argmax");
});

test("t_rows / t_cols", () => {
  const r = runFL8(`
let m = zeros(3, 5)
let r = t_rows(m)
let c = t_cols(m)
r * 10 + c
`);
  expectClose(r.val, 35, 0.001, "rows=3 cols=5");
});

test("t_fill: 상수 텐서", () => {
  const r = runFL8(`
let m = t_fill(2, 3, 7.0)
tget(m, 1, 2)
`);
  expectClose(r.val, 7.0, 0.001, "t_fill");
});

// ============================================================
// Suite 2: gpt_embedding 모듈
// ============================================================
console.log("\n── Suite 2: gpt_embedding 모듈 ────────────────────────────────");

const EMBED_SETUP = `
fn embed_seq(table: i32, ids: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(table, int(ids[i]))
    t_set_row(out, i, row)
  }
  return out
}
fn embed_forward(tok_t: i32, pos_t: i32, ids: i32, seq_len: i32, d: i32) -> i32 {
  let te = embed_seq(tok_t, ids, seq_len, d)
  let pe = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    let r = t_row(pos_t, i)
    t_set_row(pe, i, r)
  }
  return t_add(te, pe)
}
`;

test("embed_seq: shape [seq, d]", () => {
  const r = runFL8(EMBED_SETUP + `
let tab = randn(10, 8)
let ids = [2, 5, 1, 8]
let out = embed_seq(tab, ids, 4, 8)
t_rows(out) * 100 + t_cols(out)
`);
  expectClose(r.val, 408, 0.001, "embed_seq shape");
});

test("embed_forward: token+pos 덧셈", () => {
  const r = runFL8(EMBED_SETUP + `
let tok_t = zeros(10, 4)
let pos_t = ones(6, 4)
let ids = [0, 1, 2]
let out = embed_forward(tok_t, pos_t, ids, 3, 4)
tget(out, 0, 0)
`);
  expectClose(r.val, 1.0, 0.001, "embed_forward zero+one=one");
});

test("embed_lookup: 올바른 행 반환", () => {
  const r = runFL8(`
let tab = t_fill(5, 4, 0.0)
let row2 = t_fill(1, 4, 9.0)
let row2_1d = reshape(row2, 4)
t_set_row(tab, 2, row2_1d)
let got = t_row(tab, 2)
tget(got, 0, 0)
`);
  expectClose(r.val, 9.0, 0.001, "embed_lookup row2");
});

// ============================================================
// Suite 3: gpt_attention 모듈
// ============================================================
console.log("\n── Suite 3: gpt_attention 모듈 ────────────────────────────────");

const ATTN_SETUP = `
fn linear_fwd(x: i32, W: i32, b: i32, sl: i32, od: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(sl) {
    let r = t_row(out, i)
    t_set_row(out, i, t_add(r, b))
  }
  return out
}
fn row_softmax(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) {
    t_set_row(out, i, t_softmax(t_row(t, i)))
  }
  return out
}
fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32,
            sl: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, sl, d)
  let K = linear_fwd(x, Wk, bk, sl, d)
  let V = linear_fwd(x, Wv, bv, sl, d)
  let sc = t_scale(matmul(Q, transpose(K)), 1.0 / sqrt(float(d)))
  let mask = t_causal_mask(sl)
  let aw = row_softmax(t_add(sc, mask), sl, sl)
  return linear_fwd(matmul(aw, V), Wo, bo, sl, d)
}
`;

test("attn_fwd: output shape [seq, d]", () => {
  const r = runFL8(ATTN_SETUP + `
let sl = 4
let d = 8
