fn layer_fwd(x: i32, params: i32, li: i32, sl: i32, d: i32, fd: i32) -> i32 {
  let b = li * 16
  return block_fwd(x,
    params[b+0],params[b+1],params[b+2],params[b+3],
    params[b+4],params[b+5],params[b+6],params[b+7],
    params[b+8],params[b+9],params[b+10],params[b+11],
    params[b+12],params[b+13],params[b+14],params[b+15],
    sl, d, fd)
}
fn make_layer(d: i32, fd: i32) -> i32 {
  let p = []
  let i = 0
  for i in range(4) { push(p, randn(d,d)) }
  for i in range(4) { push(p, reshape(zeros(d),d)) }
  push(p, randn(d,fd))  push(p, reshape(zeros(fd),fd))
  push(p, randn(fd,d))  push(p, reshape(zeros(d),d))
  push(p, reshape(ones(d),d))  push(p, reshape(zeros(d),d))
  push(p, reshape(ones(d),d))  push(p, reshape(zeros(d),d))
