let last = t_layer_norm(t_row(x, sl-1), fls, flb, 0.00001)
let lg2d = reshape(last, 1, d)
let lg = t_row(matmul(lg2d, lm_head), 0)
let logits = t_add(lg, lm_bias)
len(shape(logits))
`);
  expect(r.val, 1, "logits는 1D");
});

