// ML 손실 함수
g.set("mse", builtin2((pred, target) => {
  const p = toAutoValues(pred);
  const t = toAutoValues(target);
  return { tag: "autograd", val: mse(p, t.map(v => v.data)) };
}));
g.set("binary_cross_entropy", builtin2((pred, target) => {
  const p = toAutoValues(pred);
  const t = toAutoValues(target);
  return { tag: "autograd", val: binaryCrossEntropy(p, t.map(v => v.data)) };
}));

// 활성화 함수
g.set("relu",    builtin1((a) => num(Math.max(0, asNum(a)))));
g.set("sigmoid", builtin1((a) => num(1 / (1 + Math.exp(-asNum(a))))));
g.set("tanh",    builtin1((a) => num(Math.tanh(asNum(a)))));

// 타입 변환
g.set("int",    builtin1((a) => num(Math.trunc(asNum(a)))));
g.set("float",  builtin1((a) => num(asNum(a))));
g.set("str",    builtin1((a) => ({ tag: "string", val: String(asNum(a)) })));
g.set("len",    builtin1((a) => {
  if (a.tag === "array") return num(a.val.length);
  if (a.tag === "tensor") return num(a.shape[0]);
  if (a.tag === "string") return num(a.val.length);
  throw new RuntimeError("len: 배열/텐서/문자열에만 사용 가능");
}));

// 범위
g.set("range", { tag: "builtin", fn: (...args) => {
  const [start, end, step] = args.length === 1
    ? [0, asNum(args[0]), 1]
    : args.length === 2
    ? [asNum(args[0]), asNum(args[1]), 1]
    : [asNum(args[0]), asNum(args[1]), asNum(args[2])];
  const arr: RuntimeValue[] = [];
  for (let i = start; i < end; i += step) arr.push(num(i));
  return { tag: "array", val: arr };
}});

// 배열 연산
g.set("push", { tag: "builtin", fn: (arr, val) => {
  if (arr.tag !== "array") throw new RuntimeError("push: 배열에만 사용 가능");
  arr.val.push(val);
  return { tag: "null" };
}});
g.set("pop", builtin1((arr) => {
  if (arr.tag !== "array") throw new RuntimeError("pop: 배열에만 사용 가능");
  return arr.val.pop() ?? { tag: "null" };
}));

