// ── Phase L: 학습 루프용 내장 함수 ──────────────────────────

// t_ce_loss(logits, target_id) → scalar (cross-entropy loss, 1D logits)
g.set("t_ce_loss", { tag: "builtin", fn: (logits, targetId) => {
  const d = asTensor(logits).data;
  const t = asNum(targetId);
  const maxV = Math.max(...d);
  const exps = d.map(v => Math.exp(v - maxV));
  const sumE = exps.reduce((a, b) => a + b, 0);
  const loss = -Math.log(exps[t] / sumE + 1e-12);
  return num(loss);
}});

// t_log_softmax(t) → 1D log-softmax 텐서
g.set("t_log_softmax", builtin1((t) => {
  const d = asTensor(t).data;
  const maxV = Math.max(...d);
  const exps = d.map(v => Math.exp(v - maxV));
