// FreeLang v8 ML — Tree-Walking Interpreter
// .fl8 파일을 AST → 직접 실행

import { Program, Stmt, Expr, TypeAnnotation } from "../ast/ast";
import { Value as AutoValue } from "../ml/autodiff";
import { MLP, Linear, ReLU, Sigmoid, Tanh, Softmax, Dropout, BatchNorm1d, Sequential, Module } from "../ml/nn";
import { Adam, SGD } from "../ml/optimizer";
import { mse, mae, huber, binaryCrossEntropy, softmaxCrossEntropy, hingeLoss } from "../ml/loss";
import { DataLoader, trainTestSplit, minMaxNormalize, zScoreNormalize, oneHot } from "../ml/dataloader";
import { Trainer } from "../ml/trainer";
import { CharTokenizer, BPETokenizer, makeNgramData } from "../ml/tokenizer";
import { MultiHeadAttention, LayerNorm, positionalEncoding } from "../ml/attention";
import { MiniGPT, TransformerBlock, Embedding, trainLM, GPTConfig } from "../ml/transformer";
import { FL8_FS } from "../stdlib/fs";
import { FL8_HTTP } from "../stdlib/http";
import { FL8_SQLITE } from "../stdlib/sqlite";
import { FL8_COLLECTIONS, FL8HashMap, FL8Queue, FL8Stack, FL8PriorityQueue, FL8Set } from "../stdlib/collections";
import { FL8_TOKENIZER, FL8Tokenizer } from "../stdlib/tokenizer";

// ============================================================
// RuntimeValue — 인터프리터가 다루는 값
// ============================================================

export type RuntimeValue =
  | { tag: "number"; val: number }
  | { tag: "bool"; val: boolean }
  | { tag: "string"; val: string }
  | { tag: "tensor"; data: number[]; shape: number[] }
  | { tag: "autograd"; val: AutoValue }
  | { tag: "array"; val: RuntimeValue[] }
  | { tag: "fn"; params: string[]; body: Stmt[]; closure: Env }
  | { tag: "builtin"; fn: (...args: RuntimeValue[]) => RuntimeValue }
  | { tag: "null" }
  | { tag: "native"; val: unknown };  // FS/HTTP/DB/Collections 등 네이티브 객체

// ============================================================
// Environment (스코프 체인)
// ============================================================

export class Env {
  private vars: Map<string, RuntimeValue> = new Map();
  constructor(public parent: Env | null = null) {}

  get(name: string): RuntimeValue {
    if (this.vars.has(name)) return this.vars.get(name)!;
    if (this.parent) return this.parent.get(name);
    throw new RuntimeError(`정의되지 않은 변수: ${name}`);
  }

  set(name: string, val: RuntimeValue): void {
    this.vars.set(name, val);
  }

  assign(name: string, val: RuntimeValue): void {
    if (this.vars.has(name)) { this.vars.set(name, val); return; }
    if (this.parent) { this.parent.assign(name, val); return; }
    throw new RuntimeError(`정의되지 않은 변수: ${name}`);
  }
}

// ============================================================
// 제어 흐름 시그널
// ============================================================

class ReturnSignal { constructor(public value: RuntimeValue) {} }
class BreakSignal {}
class ContinueSignal {}
class RuntimeError extends Error { constructor(msg: string) { super(msg); } }

// ============================================================
// Interpreter
// ============================================================

export class Interpreter {
  private globals: Env;

  constructor() {
    this.globals = new Env();
    this.registerBuiltins();
  }

  // ============================================================
  // 내장 함수 등록
  // ============================================================

  private registerBuiltins(): void {
    const g = this.globals;

    // 수학
    g.set("abs",   builtin1((a) => num(Math.abs(asNum(a)))));
    g.set("sqrt",  builtin1((a) => num(Math.sqrt(asNum(a)))));
    g.set("exp",   builtin1((a) => num(Math.exp(asNum(a)))));
    g.set("log",   builtin1((a) => num(Math.log(asNum(a)))));
    g.set("floor", builtin1((a) => num(Math.floor(asNum(a)))));
    g.set("ceil",  builtin1((a) => num(Math.ceil(asNum(a)))));
    g.set("round", builtin1((a) => num(Math.round(asNum(a)))));
    g.set("sin",   builtin1((a) => num(Math.sin(asNum(a)))));
    g.set("cos",   builtin1((a) => num(Math.cos(asNum(a)))));
    g.set("max",   builtin2((a, b) => num(Math.max(asNum(a), asNum(b)))));
    g.set("min",   builtin2((a, b) => num(Math.min(asNum(a), asNum(b)))));
    g.set("pow",   builtin2((a, b) => num(Math.pow(asNum(a), asNum(b)))));

    // I/O
    g.set("print", { tag: "builtin", fn: (...args) => {
      console.log(...args.map(v => this.display(v)));
      return { tag: "null" };
    }});
    g.set("println", { tag: "builtin", fn: (...args) => {
      console.log(...args.map(v => this.display(v)));
      return { tag: "null" };
    }});

    // Tensor 생성
    g.set("zeros", { tag: "builtin", fn: (...args) => {
      const shape = args.map(a => asNum(a));
      const size = shape.reduce((a, b) => a * b, 1);
      return { tag: "tensor", data: Array(size).fill(0), shape };
    }});
    g.set("ones", { tag: "builtin", fn: (...args) => {
      const shape = args.map(a => asNum(a));
      const size = shape.reduce((a, b) => a * b, 1);
      return { tag: "tensor", data: Array(size).fill(1), shape };
    }});
    g.set("randn", { tag: "builtin", fn: (...args) => {
      const shape = args.map(a => asNum(a));
      const size = shape.reduce((a, b) => a * b, 1);
      const data = Array.from({ length: size }, () => {
        // Box-Muller 정규분포
        const u1 = Math.random(), u2 = Math.random();
        return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2) * 0.1;
      });
      return { tag: "tensor", data, shape };
    }});
    g.set("tensor", { tag: "builtin", fn: (...args) => {
      // tensor([1,2,3,4], [2,2]) 또는 tensor([1,2,3,4])
      const data = asArr(args[0]).map(v => asNum(v));
      const shape = args.length > 1 ? asArr(args[1]).map(v => asNum(v)) : [data.length];
      return { tag: "tensor", data, shape };
    }});

    // Tensor 2D set/get (뮤터블 인덱싱)
    g.set("tset", { tag: "builtin", fn: (t, i, j, val) => {
      const tensor = asTensor(t);
      const cols = tensor.shape[1];
      tensor.data[asNum(i) * cols + asNum(j)] = asNum(val);
      return { tag: "null" };
    }});
    g.set("tget", { tag: "builtin", fn: (t, i, j) => {
      const tensor = asTensor(t);
      const cols = tensor.shape[1];
      return num(tensor.data[asNum(i) * cols + asNum(j)]);
    }});

    // Tensor 3D set/get
    g.set("tset3", { tag: "builtin", fn: (t, i, j, k, val) => {
      const tensor = asTensor(t);
      const [, d1, d2] = tensor.shape;
      tensor.data[asNum(i) * d1 * d2 + asNum(j) * d2 + asNum(k)] = asNum(val);
      return { tag: "null" };
    }});
    g.set("tget3", { tag: "builtin", fn: (t, i, j, k) => {
      const tensor = asTensor(t);
      const [, d1, d2] = tensor.shape;
      return num(tensor.data[asNum(i) * d1 * d2 + asNum(j) * d2 + asNum(k)]);
    }});
    // 3D 슬라이스: 2D 행렬 추출 t3d_slice(t, i) → t[i, :, :]
    g.set("t3d_slice", { tag: "builtin", fn: (t, i) => {
      const tensor = asTensor(t);
      const [, d1, d2] = tensor.shape;
      const ii = asNum(i);
      return { tag: "tensor", data: tensor.data.slice(ii * d1 * d2, (ii + 1) * d1 * d2), shape: [d1, d2] };
    }});
    // 3D 쓰기: t3d_write(dst, i, src_2d)
    g.set("t3d_write", { tag: "builtin", fn: (t, i, src) => {
      const tensor = asTensor(t);
      const srcT = asTensor(src);
      const [, d1, d2] = tensor.shape;
      const ii = asNum(i);
      for (let k = 0; k < d1 * d2; k++) tensor.data[ii * d1 * d2 + k] = srcT.data[k];
      return { tag: "null" };
    }});

    // Scalar autograd (Value)
    g.set("val",      builtin1((a)    => ({ tag: "autograd", val: new AutoValue(asNum(a)) })));
    g.set("val_add",  builtin2((a, b) => ({ tag: "autograd", val: asAV(a).add(asAV(b)) })));
    g.set("val_mul",  builtin2((a, b) => ({ tag: "autograd", val: asAV(a).mul(asAV(b)) })));
    g.set("val_relu", builtin1((a)    => ({ tag: "autograd", val: asAV(a).relu() })));
    g.set("val_tanh", builtin1((a)    => ({ tag: "autograd", val: asAV(a).tanh() })));
    g.set("val_pow",  builtin2((a, e) => ({ tag: "autograd", val: asAV(a).pow(asNum(e)) })));
    g.set("val_backward", builtin1((a) => { asAV(a).backward(); return { tag: "null" }; }));
    g.set("val_data", builtin1((a)    => num(asAV(a).data)));
    g.set("val_grad", builtin1((a)    => num(asAV(a).grad)));

    // Tensor 연산
    g.set("matmul", builtin2((a, b) => tensorMatmul(asTensor(a), asTensor(b))));
    g.set("transpose", builtin1((a) => tensorTranspose(asTensor(a))));
    g.set("reshape", { tag: "builtin", fn: (a, ...dims) => {
      const t = asTensor(a);
      const newShape = dims.map(d => asNum(d));
      return { tag: "tensor", data: t.data.slice(), shape: newShape };
    }});
    g.set("shape", builtin1((a) => {
      const t = asTensor(a);
      return { tag: "array", val: t.shape.map(s => num(s)) };
    }));

    // ── Phase K: GPT용 tensor 연산 ──────────────────────────────
    // t_add(a, b) → elementwise 덧셈 (같은 shape)
    g.set("t_add", builtin2((a, b) => {
      const ta = asTensor(a), tb = asTensor(b);
      if (ta.data.length !== tb.data.length)
        throw new RuntimeError(`t_add: shape 불일치 [${ta.shape}] vs [${tb.shape}]`);
      return { tag: "tensor", data: ta.data.map((v, i) => v + tb.data[i]), shape: ta.shape.slice() };
    }));

    // t_sub(a, b) → elementwise 뺄셈
    g.set("t_sub", builtin2((a, b) => {
      const ta = asTensor(a), tb = asTensor(b);
      if (ta.data.length !== tb.data.length)
        throw new RuntimeError(`t_sub: shape 불일치`);
      return { tag: "tensor", data: ta.data.map((v, i) => v - tb.data[i]), shape: ta.shape.slice() };
    }));

    // t_mul(a, b) → elementwise 곱셈
    g.set("t_mul", builtin2((a, b) => {
      const ta = asTensor(a), tb = asTensor(b);
      if (ta.data.length !== tb.data.length)
        throw new RuntimeError(`t_mul: shape 불일치`);
      return { tag: "tensor", data: ta.data.map((v, i) => v * tb.data[i]), shape: ta.shape.slice() };
    }));

    // t_scale(t, s) → scalar 곱
    g.set("t_scale", builtin2((t, s) => {
      const ta = asTensor(t);
      const sc = asNum(s);
      return { tag: "tensor", data: ta.data.map(v => v * sc), shape: ta.shape.slice() };
    }));

    // t_sum(t) → scalar (전체 합)
    g.set("t_sum", builtin1((t) => num(asTensor(t).data.reduce((a, b) => a + b, 0))));

    // t_mean(t) → scalar (전체 평균)
    g.set("t_mean", builtin1((t) => {
      const d = asTensor(t).data;
      return num(d.reduce((a, b) => a + b, 0) / d.length);
    }));

    // t_row(t, i) → i번째 행 (1D tensor)  [rows, cols] → [cols]
    g.set("t_row", builtin2((t, i) => {
      const ta = asTensor(t);
      const cols = ta.shape[ta.shape.length - 1];
      const ii = asNum(i);
      return { tag: "tensor", data: ta.data.slice(ii * cols, (ii + 1) * cols), shape: [cols] };
    }));

    // t_set_row(t, i, row) → t[i] = row  (in-place)
    g.set("t_set_row", { tag: "builtin", fn: (t, i, row) => {
      const ta = asTensor(t);
      const rowT = asTensor(row);
      const cols = ta.shape[ta.shape.length - 1];
      const ii = asNum(i);
      for (let k = 0; k < cols; k++) ta.data[ii * cols + k] = rowT.data[k];
      return { tag: "null" };
    }});

    // t_copy(t) → deep copy
    g.set("t_copy", builtin1((t) => {
      const ta = asTensor(t);
      return { tag: "tensor", data: ta.data.slice(), shape: ta.shape.slice() };
    }));

    // t_softmax(t) → softmax (1D, numerically stable)
    g.set("t_softmax", builtin1((t) => {
      const d = asTensor(t).data;
      const max = Math.max(...d);
      const exps = d.map(v => Math.exp(v - max));
      const sum = exps.reduce((a, b) => a + b, 0);
      return { tag: "tensor", data: exps.map(v => v / sum), shape: asTensor(t).shape.slice() };
    }));

    // t_layer_norm(t, scale, bias, eps) → LayerNorm 1D
    g.set("t_layer_norm", { tag: "builtin", fn: (t, scale, bias, eps) => {
      const d  = asTensor(t).data;
      const sc = asTensor(scale).data;
      const bi = asTensor(bias).data;
      const ep = eps ? asNum(eps) : 1e-5;
      const mean = d.reduce((a, b) => a + b, 0) / d.length;
      const variance = d.reduce((a, v) => a + (v - mean) ** 2, 0) / d.length;
      const std = Math.sqrt(variance + ep);
      const out = d.map((v, i) => sc[i] * (v - mean) / std + bi[i]);
      return { tag: "tensor", data: out, shape: asTensor(t).shape.slice() };
    }});

    // t_gelu(t) → GELU activation (1D/nD elementwise)
    g.set("t_gelu", builtin1((t) => {
      const d = asTensor(t).data;
      const out = d.map(v => {
        const c = 0.7978845608028654;
        const cubic = v + 0.044715 * v * v * v;
        return 0.5 * v * (1 + Math.tanh(c * cubic));
      });
      return { tag: "tensor", data: out, shape: asTensor(t).shape.slice() };
    }));

    // t_relu(t) → ReLU elementwise
    g.set("t_relu", builtin1((t) => {
      const d = asTensor(t).data;
      return { tag: "tensor", data: d.map(v => Math.max(0, v)), shape: asTensor(t).shape.slice() };
    }));

    // t_rows(t) → 행 수
    g.set("t_rows", builtin1((t) => num(asTensor(t).shape[0])));
    // t_cols(t) → 열 수
    g.set("t_cols", builtin1((t) => num(asTensor(t).shape[1] ?? 1)));

    // t_causal_mask(seq_len) → [seq_len, seq_len] 하삼각 마스크 (1=attend, -1e9=mask)
    g.set("t_causal_mask", builtin1((n) => {
      const sz = asNum(n);
      const data = Array.from({ length: sz * sz }, (_, k) => {
        const r = Math.floor(k / sz), c = k % sz;
        return r >= c ? 0.0 : -1e9;
      });
      return { tag: "tensor", data, shape: [sz, sz] };
    }));

    // t_argmax(t) → 최댓값 인덱스 (1D)
    g.set("t_argmax", builtin1((t) => {
      const d = asTensor(t).data;
      let best = 0;
      for (let i = 1; i < d.length; i++) if (d[i] > d[best]) best = i;
      return num(best);
    }));

    // t_fill(rows, cols, val) → [rows, cols] 텐서 (상수 채우기)
    g.set("t_fill", { tag: "builtin", fn: (rows, cols, val) => {
      const r = asNum(rows), c = asNum(cols), v = asNum(val);
      return { tag: "tensor", data: Array(r * c).fill(v), shape: [r, c] };
    }});

    // ML 손실 함수
    g.set("mse", builtin2((pred, target) => {
      const p = toAutoValues(pred);
      const t = toAutoValues(target);
      return { tag: "autograd", val: mse(p, t.map(v => v.data)) };
    }));
    g.set("binary_cross_entropy", builtin2((pred, target) => {
      const p = toAutoValues(pred);
      const t = toAutoValues(target);
      return { tag: "autograd", val: binaryCrossEntropy(p, t.map(v => v.data)) };
    }));

    // 활성화 함수
    g.set("relu",    builtin1((a) => num(Math.max(0, asNum(a)))));
    g.set("sigmoid", builtin1((a) => num(1 / (1 + Math.exp(-asNum(a))))));
    g.set("tanh",    builtin1((a) => num(Math.tanh(asNum(a)))));

    // 타입 변환
    g.set("int",    builtin1((a) => num(Math.trunc(asNum(a)))));
    g.set("float",  builtin1((a) => num(asNum(a))));
    g.set("str",    builtin1((a) => ({ tag: "string", val: String(asNum(a)) })));
    g.set("len",    builtin1((a) => {
      if (a.tag === "array") return num(a.val.length);
      if (a.tag === "tensor") return num(a.shape[0]);
      if (a.tag === "string") return num(a.val.length);
      throw new RuntimeError("len: 배열/텐서/문자열에만 사용 가능");
    }));

    // 범위
    g.set("range", { tag: "builtin", fn: (...args) => {
      const [start, end, step] = args.length === 1
        ? [0, asNum(args[0]), 1]
        : args.length === 2
        ? [asNum(args[0]), asNum(args[1]), 1]
        : [asNum(args[0]), asNum(args[1]), asNum(args[2])];
      const arr: RuntimeValue[] = [];
      for (let i = start; i < end; i += step) arr.push(num(i));
      return { tag: "array", val: arr };
    }});

    // 배열 연산
    g.set("push", { tag: "builtin", fn: (arr, val) => {
      if (arr.tag !== "array") throw new RuntimeError("push: 배열에만 사용 가능");
      arr.val.push(val);
      return { tag: "null" };
    }});
    g.set("pop", builtin1((arr) => {
      if (arr.tag !== "array") throw new RuntimeError("pop: 배열에만 사용 가능");
      return arr.val.pop() ?? { tag: "null" };
    }));
    g.set("map", builtin2((arr, fn) => {
      if (arr.tag !== "array") throw new RuntimeError("map: 배열에만 사용 가능");
      return { tag: "array", val: arr.val.map(v => this.callFn(fn, [v])) };
    }));
    g.set("filter", builtin2((arr, fn) => {
      if (arr.tag !== "array") throw new RuntimeError("filter: 배열에만 사용 가능");
      return { tag: "array", val: arr.val.filter(v => isTruthy(this.callFn(fn, [v]))) };
    }));
    g.set("reduce", { tag: "builtin", fn: (arr, fn, init) => {
      if (arr.tag !== "array") throw new RuntimeError("reduce: 배열에만 사용 가능");
      return arr.val.reduce((acc, v) => this.callFn(fn, [acc, v]), init);
    }});

    // ML 손실 함수 추가
    g.set("mae", builtin2((pred, target) => {
      const p = toAutoValues(pred);
      const t = toAutoValues(target);
      return { tag: "autograd", val: mae(p, t.map(v => v.data)) };
    }));
    g.set("huber", { tag: "builtin", fn: (pred, target, delta?) => {
      const p = toAutoValues(pred);
      const t = toAutoValues(target);
      return { tag: "autograd", val: huber(p, t.map(v => v.data), delta ? asNum(delta) : 1.0) };
    }});
    g.set("cross_entropy", { tag: "builtin", fn: (logits, targetClass) => {
      const p = toAutoValues(logits);
      return { tag: "autograd", val: softmaxCrossEntropy(p, asNum(targetClass)) };
    }});
    g.set("hinge_loss", builtin2((pred, target) => {
      const p = toAutoValues(pred);
      const t = toAutoValues(target);
      return { tag: "autograd", val: hingeLoss(p, t.map(v => v.data)) };
    }));

    // NN 레이어 생성자
    g.set("Linear", builtin2((nin, nout) => makeModuleObject(new Linear(asNum(nin), asNum(nout)), "Linear")));
    g.set("ReLU",    { tag: "builtin", fn: () => makeModuleObject(new ReLU(), "ReLU") });
    g.set("Sigmoid", { tag: "builtin", fn: () => makeModuleObject(new Sigmoid(), "Sigmoid") });
    g.set("Tanh",    { tag: "builtin", fn: () => makeModuleObject(new Tanh(), "Tanh") });
    g.set("Softmax", { tag: "builtin", fn: () => makeModuleObject(new Softmax(), "Softmax") });
    g.set("Dropout", { tag: "builtin", fn: (rate?) => makeModuleObject(new Dropout(rate ? asNum(rate) : 0.5), "Dropout") });
    g.set("BatchNorm1d", builtin1((features) => makeModuleObject(new BatchNorm1d(asNum(features)), "BatchNorm1d")));
    g.set("Sequential", { tag: "builtin", fn: (...layers) => {
      const mods = layers.map(l => {
        if ((l as any).__type === "ModuleObject") return (l as any).__module as Module;
        if ((l as any).__type === "MLPObject") return (l as any).__model as Module;
        throw new RuntimeError("Sequential: Module 필요");
      });
      return makeModuleObject(new Sequential(mods), "Sequential");
    }});

    // 데이터 처리
    g.set("one_hot", builtin2((labels, numClasses) => {
      const ls = asArr(labels).map(v => asNum(v));
      const nc = asNum(numClasses);
      return { tag: "array", val: oneHot(ls, nc).map(row => ({ tag: "array", val: row.map(v => num(v)) })) };
    }));
    g.set("normalize", builtin1((X) => {
      const data = to2DArray(X);
      const { normalized } = minMaxNormalize(data);
      return { tag: "array", val: normalized.map(row => ({ tag: "array", val: row.map(v => num(v)) })) };
    }));
    g.set("zscore", builtin1((X) => {
      const data = to2DArray(X);
      const { normalized } = zScoreNormalize(data);
      return { tag: "array", val: normalized.map(row => ({ tag: "array", val: row.map(v => num(v)) })) };
    }));

    // MLP 생성자 → MLPObject 반환
    g.set("MLP", { tag: "builtin", fn: (inputSize, ...layerSizes) => {
      const sizes = [inputSize, ...layerSizes].map(v => asNum(v));
      const inputDim = sizes[0];
      const layers = sizes.slice(1);
      const model = new MLP(inputDim, layers);
      return makeMlpObject(model);
    }});

    // Adam 생성자 → AdamObject 반환
    g.set("Adam", { tag: "builtin", fn: (lr) => {
      const optim = new Adam(asNum(lr ?? num(0.001)));
      return makeAdamObject(optim);
    }});
    g.set("SGD", { tag: "builtin", fn: (lr) => {
      const optim = new SGD(asNum(lr ?? num(0.01)));
      return makeSgdObject(optim);
    }});

    // ============================================================
    // Phase 5: LLM / Transformer 내장
    // ============================================================

    // 토크나이저
    g.set("CharTokenizer", { tag: "builtin", fn: () => makeTokenizerObject(new CharTokenizer()) });
    g.set("BPETokenizer", { tag: "builtin", fn: () => makeTokenizerObject(new BPETokenizer()) });

    // MiniGPT 생성
    g.set("MiniGPT", { tag: "builtin", fn: (vocabSize, dModel, numHeads, numLayers, maxSeqLen) => {
      const config: GPTConfig = {
        vocabSize: asNum(vocabSize),
        dModel: asNum(dModel),
        numHeads: asNum(numHeads),
        numLayers: asNum(numLayers),
        maxSeqLen: asNum(maxSeqLen),
      };
      return makeGPTObject(new MiniGPT(config));
    }});

    // Transformer 구성 요소
    g.set("LayerNorm", { tag: "builtin", fn: (dModel) => {
      const ln = new LayerNorm(asNum(dModel));
      return makeModuleObject({
        name: "LayerNorm",
        forward: (x: AutoValue[]) => ln.forward(x),
        params: () => ln.params()
      }, "LayerNorm");
    }});
    g.set("Embedding", { tag: "builtin", fn: (vocabSize, dModel) => {
      const emb = new Embedding(asNum(vocabSize), asNum(dModel));
      return makeModuleObject({
        name: "Embedding",
        forward: (x: AutoValue[]) => x,
        params: () => emb.params(),
      }, "Embedding");
    }});

    // 위치 인코딩
    g.set("positional_encoding", builtin2((seqLen, dModel) => {
      const pe = positionalEncoding(asNum(seqLen), asNum(dModel));
      return { tag: "tensor", data: pe.flat(), shape: [asNum(seqLen), asNum(dModel)] };
    }));

    // 언어 모델 학습 유틸
    g.set("make_ngram_data", { tag: "builtin", fn: (ids, seqLen) => {
      const idArr = asArr(ids).map(v => asNum(v));
      const { inputs, targets } = makeNgramData(idArr, asNum(seqLen));
      return {
        tag: "array",
        val: [
          { tag: "array", val: inputs.map(row => ({ tag: "array", val: row.map(v => num(v)) })) },
          { tag: "array", val: targets.map(row => ({ tag: "array", val: row.map(v => num(v)) })) },
        ]
      };
    }});

    // ============================================================
    // Phase 9: 표준 라이브러리 (FS / HTTP / SQLite / Collections)
    // ============================================================

    const native = (v: unknown): RuntimeValue => ({ tag: "native", val: v });
    const fromNative = (rv: RuntimeValue): unknown => rv.tag === "native" ? rv.val : rv.tag === "string" ? rv.val : rv.tag === "number" ? rv.val : rv.tag === "bool" ? rv.val : rv.tag === "null" ? null : rv;
    const toRV = (v: unknown): RuntimeValue => {
      if (v === null || v === undefined) return { tag: "null" };
      if (typeof v === "number") return num(v);
      if (typeof v === "boolean") return { tag: "bool", val: v };
      if (typeof v === "string") return { tag: "string", val: v };
      if (Array.isArray(v)) return { tag: "array", val: v.map(toRV) };
      if (typeof v === "object") return native(v);
      return { tag: "null" };
    };

    // ── 파일 시스템 ──────────────────────────────────────────────
    g.set("fs_read",      builtin1((p) => toRV(FL8_FS.read(asStr(p)))));
    g.set("fs_write",     builtin2((p, c) => toRV(FL8_FS.write(asStr(p), asStr(c)))));
    g.set("fs_append",    builtin2((p, c) => toRV(FL8_FS.append(asStr(p), asStr(c)))));
    g.set("fs_delete",    builtin1((p) => toRV(FL8_FS.delete(asStr(p)))));
    g.set("fs_exists",    builtin1((p) => toRV(FL8_FS.exists(asStr(p)))));
    g.set("fs_ls",        builtin1((p) => toRV(FL8_FS.ls(asStr(p)))));
    g.set("fs_mkdir",     builtin1((p) => toRV(FL8_FS.mkdir(asStr(p)))));
    g.set("fs_read_json", builtin1((p) => toRV(FL8_FS.readJson(asStr(p)))));
    g.set("fs_write_json",builtin2((p, d) => toRV(FL8_FS.writeJson(asStr(p), fromNative(d)))));
    g.set("fs_join",      { tag: "builtin", fn: (...parts) => toRV(FL8_FS.join(...parts.map(asStr))) });
    g.set("fs_cwd",       { tag: "builtin", fn: () => toRV(FL8_FS.cwd()) });
    g.set("fs_home",      { tag: "builtin", fn: () => toRV(FL8_FS.homeDir()) });

    // ── HTTP ─────────────────────────────────────────────────────
    g.set("http_get",      builtin1((url) => {
      const r = FL8_HTTP.get(asStr(url));
      return { tag: "array", val: [num(r.status), { tag: "string", val: r.body }, { tag: "bool", val: r.ok }] };
    }));
    g.set("http_post",     builtin2((url, body) => {
      const b = body.tag === "string" ? body.val : JSON.stringify(fromNative(body));
      const r = FL8_HTTP.post(asStr(url), b as unknown as object);
      return { tag: "array", val: [num(r.status), { tag: "string", val: r.body }, { tag: "bool", val: r.ok }] };
    }));
    g.set("http_get_json", builtin1((url) => toRV(FL8_HTTP.getJson(asStr(url)))));
    g.set("http_post_json",builtin2((url, data) => toRV(FL8_HTTP.postJson(asStr(url), fromNative(data) as object))));

    // ── SQLite (인메모리 DB) ──────────────────────────────────────
    g.set("db_open",   builtin1((p) => toRV(FL8_SQLITE.open(asStr(p)))));
    g.set("db_memory", { tag: "builtin", fn: () => toRV(FL8_SQLITE.inMemory()) });
    g.set("db_close",  builtin1((h) => { FL8_SQLITE.close(asStr(h)); return { tag: "null" }; }));
    g.set("db_query",  builtin2((h, sql) => {
      const r = FL8_SQLITE.query(asStr(h), asStr(sql));
      return toRV(r.rows);
    }));
    g.set("db_create_table", { tag: "builtin", fn: (h, name, ...cols) => {
      FL8_SQLITE.createTable(asStr(h), asStr(name), cols.map(asStr));
      return { tag: "null" };
    }});
    g.set("db_insert",  { tag: "builtin", fn: (h, table, ...kv) => {
      // kv: key1, val1, key2, val2, ...
      const row: Record<string, unknown> = {};
      for (let i = 0; i < kv.length - 1; i += 2) {
        row[asStr(kv[i])] = fromNative(kv[i + 1]);
      }
      return num(FL8_SQLITE.insert(asStr(h), asStr(table), row as any));
    }});
    g.set("db_select",  builtin2((h, table) => toRV(FL8_SQLITE.select(asStr(h), asStr(table)))));
    g.set("db_count",   builtin2((h, table) => num(FL8_SQLITE.count(asStr(h), asStr(table)))));
    g.set("db_save",    builtin1((h) => toRV(FL8_SQLITE.save(asStr(h)))));

    // ── Collections ──────────────────────────────────────────────
    g.set("HashMap",   { tag: "builtin", fn: () => native(new FL8HashMap()) });
    g.set("hm_set",    { tag: "builtin", fn: (m, k, v) => { (m as any).val.set(fromNative(k), fromNative(v)); return { tag: "null" }; } });
    g.set("hm_get",    builtin2((m, k) => toRV((m as any).val.get(fromNative(k)))));
    g.set("hm_get_or", { tag: "builtin", fn: (m, k, d) => toRV((m as any).val.getOr(fromNative(k), fromNative(d))) });
    g.set("hm_has",    builtin2((m, k) => ({ tag: "bool", val: (m as any).val.has(fromNative(k)) })));
    g.set("hm_delete", builtin2((m, k) => ({ tag: "bool", val: (m as any).val.delete(fromNative(k)) })));
    g.set("hm_size",   builtin1((m) => num((m as any).val.size())));
    g.set("hm_keys",   builtin1((m) => toRV((m as any).val.keys())));
    g.set("hm_values", builtin1((m) => toRV((m as any).val.values())));

    g.set("Queue",       { tag: "builtin", fn: () => native(new FL8Queue()) });
    g.set("q_enqueue",   builtin2((q, v) => { (q as any).val.enqueue(fromNative(v)); return { tag: "null" }; }));
    g.set("q_dequeue",   builtin1((q) => toRV((q as any).val.dequeue())));
    g.set("q_peek",      builtin1((q) => toRV((q as any).val.peek())));
    g.set("q_is_empty",  builtin1((q) => ({ tag: "bool", val: (q as any).val.isEmpty() })));
    g.set("q_size",      builtin1((q) => num((q as any).val.size())));

    g.set("Stack",       { tag: "builtin", fn: () => native(new FL8Stack()) });
    g.set("s_push",      builtin2((s, v) => { (s as any).val.push(fromNative(v)); return { tag: "null" }; }));
    g.set("s_pop",       builtin1((s) => toRV((s as any).val.pop())));
    g.set("s_peek",      builtin1((s) => toRV((s as any).val.peek())));
    g.set("s_is_empty",  builtin1((s) => ({ tag: "bool", val: (s as any).val.isEmpty() })));
    g.set("s_size",      builtin1((s) => num((s as any).val.size())));

    g.set("PriorityQueue", { tag: "builtin", fn: () => native(new FL8PriorityQueue()) });
    g.set("pq_enqueue",  { tag: "builtin", fn: (pq, v, p) => { (pq as any).val.enqueue(fromNative(v), asNum(p)); return { tag: "null" }; } });
    g.set("pq_dequeue",  builtin1((pq) => toRV((pq as any).val.dequeue())));
    g.set("pq_peek",     builtin1((pq) => toRV((pq as any).val.peek())));
    g.set("pq_is_empty", builtin1((pq) => ({ tag: "bool", val: (pq as any).val.isEmpty() })));
    g.set("pq_size",     builtin1((pq) => num((pq as any).val.size())));

    // ── Phase J: GPT Tokenizer ──────────────────────────────────
    const asTok = (v: RuntimeValue): FL8Tokenizer => {
      if (v.tag !== "native") throw new RuntimeError("tok: tokenizer 핸들 필요");
      return v.val as FL8Tokenizer;
    };
    const asStrVal = (v: RuntimeValue): string => {
      if (v.tag === "string") return v.val;
      if (v.tag === "number") return String(v.val);
      throw new RuntimeError("tok: 문자열 인수 필요");
    };

    // tok_load(path) → native Tokenizer
    g.set("tok_load", builtin1((p) => {
      try {
        const tok = FL8_TOKENIZER.load(asStrVal(p));
        return native(tok);
      } catch (e: any) {
        throw new RuntimeError(`tok_load: ${e.message}`);
      }
    }));

    // tok_make(flat_array) → native Tokenizer
    // flat_array: [token0, id0, token1, id1, ...] 플랫 배열
    // 또는 native FL8Tokenizer
    g.set("tok_make", builtin1((v) => {
      if (v.tag === "native") return native(v.val as FL8Tokenizer);
      if (v.tag === "tensor") {
        // tensor 형태로 들어온 경우 (2D 배열이 tensor_lit으로 파싱됨)
        // tensor.data: [s0, id0, s1, id1, ...] — 문자열은 별도 처리
        throw new RuntimeError("tok_make: FL8 배열 리터럴은 플랫 배열로 전달하세요. [tok0, id0, tok1, id1, ...]");
      }
      if (v.tag === "array") {
        // [token0, id0, token1, id1, ...] 플랫 형태
        const vocabObj: Record<string, number> = {};
        for (let i = 0; i + 1 < v.val.length; i += 2) {
          const token = asStrVal(v.val[i]);
          const id    = asNum(v.val[i + 1]);
          vocabObj[token] = id;
        }
        return native(FL8_TOKENIZER.make(vocabObj));
      }
      throw new RuntimeError("tok_make: 배열 또는 native vocab 필요");
    }));

    // tok_encode(tok, text) → [id, ...]
    g.set("tok_encode", builtin2((tok, text) => {
      const ids = FL8_TOKENIZER.encode(asTok(tok), asStrVal(text));
      return { tag: "array", val: ids.map(id => num(id)) };
    }));

    // tok_decode(tok, ids) → string
    g.set("tok_decode", builtin2((tok, ids) => {
      if (ids.tag !== "array") throw new RuntimeError("tok_decode: 배열 필요");
      const numIds = ids.val.map(v => asNum(v));
      return { tag: "string", val: FL8_TOKENIZER.decode(asTok(tok), numIds) };
    }));

    // tok_vocab_size(tok) → number
    g.set("tok_vocab_size", builtin1((tok) => num(FL8_TOKENIZER.vocabSize(asTok(tok)))));

    // tok_token(tok, id) → string
    g.set("tok_token", builtin2((tok, id) => ({
      tag: "string", val: FL8_TOKENIZER.token(asTok(tok), asNum(id))
    })));

    // tok_id(tok, token) → number
    g.set("tok_id", builtin2((tok, token) => num(FL8_TOKENIZER.id(asTok(tok), asStrVal(token)))));

    // tok_special(tok, name) → number  ("pad"|"unk"|"bos"|"eos")
    g.set("tok_special", builtin2((tok, name) => num(FL8_TOKENIZER.special(asTok(tok), asStrVal(name)))));

    // tok_top_words(tok) → [string, ...]
    g.set("tok_top_words", builtin1((tok) => ({
      tag: "array",
      val: FL8_TOKENIZER.topWords(asTok(tok)).map(w => ({ tag: "string" as const, val: w }))
    })));
  }

  // ============================================================
  // 프로그램 실행
  // ============================================================

  run(program: Program): RuntimeValue {
    const env = new Env(this.globals);
    let last: RuntimeValue = { tag: "null" };
    for (const stmt of program.stmts) {
      const r = this.execStmt(stmt, env);
      if (r instanceof ReturnSignal) break;
      if (!(r instanceof BreakSignal) && !(r instanceof ContinueSignal) && r && 'tag' in (r as any)) last = r as RuntimeValue;
    }
    return last;
  }

  // REPL 전용: globals 스코프에서 직접 실행 (상태 지속)
  runInGlobal(program: Program): RuntimeValue {
    let last: RuntimeValue = { tag: "null" };
    for (const stmt of program.stmts) {
      const r = this.execStmt(stmt, this.globals);
      if (r instanceof ReturnSignal) break;
      if (!(r instanceof BreakSignal) && !(r instanceof ContinueSignal) && r && 'tag' in (r as any)) last = r as RuntimeValue;
    }
    return last;
  }

  // REPL 전용: 전역 변수/함수 이름 목록 반환
  getGlobalNames(): string[] {
    return [...(this.globals as any).vars.keys()];
  }

  // ============================================================
  // 문 실행
  // ============================================================

  private execStmt(stmt: Stmt, env: Env): RuntimeValue | ReturnSignal | BreakSignal | ContinueSignal {
    switch (stmt.kind) {
      case "var_decl": {
        const val = this.evalExpr(stmt.init, env);
        env.set(stmt.name, val);
        return { tag: "null" };
      }

      case "fn_decl": {
        const fn: RuntimeValue = {
          tag: "fn",
          params: stmt.params.map(p => p.name),
          body: stmt.body,
          closure: env,
        };
        env.set(stmt.name, fn);
        return { tag: "null" };
      }

      case "expr_stmt": {
        // grad_block 특별 처리
        if (stmt.expr.kind === "grad_block") {
          for (const s of stmt.expr.body) {
            const r = this.execStmt(s, new Env(env));
            if (r instanceof ReturnSignal) return r;
          }
          return { tag: "null" };
        }
        const v = this.evalExpr(stmt.expr, env);
        return v;
      }

      case "if_stmt": {
        const cond = this.evalExpr(stmt.condition, env);
        if (isTruthy(cond)) {
          return this.execBlock(stmt.then, new Env(env));
        } else if (stmt.else_) {
          return this.execBlock(stmt.else_, new Env(env));
        }
        return { tag: "null" };
      }

      case "while_stmt": {
        while (true) {
          const cond = this.evalExpr(stmt.condition, env);
          if (!isTruthy(cond)) break;
          const r = this.execBlock(stmt.body, new Env(env));
          if (r instanceof ReturnSignal) return r;
          if (r instanceof BreakSignal) break;
          if (r instanceof ContinueSignal) continue;
        }
        return { tag: "null" };
      }

      case "for_stmt": {
        const start = this.evalExpr(stmt.iterable, env);
        // range: iterable이 number면 0..n
        let items: RuntimeValue[];
        if (start.tag === "number") {
          items = Array.from({ length: start.val }, (_, i) => num(i));
        } else if (start.tag === "array") {
          items = start.val;
        } else if (start.tag === "tensor") {
          items = start.data.map(v => num(v));
        } else {
          throw new RuntimeError(`for: 이터러블 아님 (${start.tag})`);
        }
        for (const item of items) {
          const loopEnv = new Env(env);
          loopEnv.set(stmt.variable, item);
          const r = this.execBlock(stmt.body, loopEnv);
          if (r instanceof ReturnSignal) return r;
          if (r instanceof BreakSignal) break;
          if (r instanceof ContinueSignal) continue;
        }
        return { tag: "null" };
      }

      case "for_of_stmt": {
        const iterable = this.evalExpr(stmt.iterable, env);
        let items: RuntimeValue[];
        if (iterable.tag === "array") items = iterable.val;
        else if (iterable.tag === "tensor") items = iterable.data.map(v => num(v));
        else throw new RuntimeError(`for of: 이터러블 아님 (${iterable.tag})`);
        for (const item of items) {
          const loopEnv = new Env(env);
          loopEnv.set(stmt.variable, item);
          const r = this.execBlock(stmt.body, loopEnv);
          if (r instanceof ReturnSignal) return r;
          if (r instanceof BreakSignal) break;
          if (r instanceof ContinueSignal) continue;
        }
        return { tag: "null" };
      }

      case "return_stmt": {
        const val = stmt.value ? this.evalExpr(stmt.value, env) : { tag: "null" as const };
        return new ReturnSignal(val);
      }

      case "break_stmt": return new BreakSignal();
      case "continue_stmt": return new ContinueSignal();

      case "struct_decl": return { tag: "null" }; // 타입 선언만
      case "match_stmt": {
        const subject = this.evalExpr(stmt.subject, env);
        for (const arm of stmt.arms) {
          const bindings = matchPattern(arm.pattern, subject);
          if (bindings !== null) {
            const armEnv = new Env(env);
            for (const [k, v] of Object.entries(bindings)) armEnv.set(k, v);
            return { tag: "null" };
          }
        }
        return { tag: "null" };
      }

      default:
        return { tag: "null" };
    }
  }

  private execBlock(stmts: Stmt[], env: Env): RuntimeValue | ReturnSignal | BreakSignal | ContinueSignal {
    let last: RuntimeValue = { tag: "null" };
    for (const stmt of stmts) {
      const r = this.execStmt(stmt, env);
      if (r instanceof ReturnSignal || r instanceof BreakSignal || r instanceof ContinueSignal) return r;
      last = r as RuntimeValue;
    }
    return last;
  }

  // ============================================================
  // 식 평가
  // ============================================================

  evalExpr(expr: Expr, env: Env): RuntimeValue {
    switch (expr.kind) {
      case "int_lit":   return num(expr.value);
      case "float_lit": return num(expr.value);
      case "bool_lit":  return { tag: "bool", val: expr.value };
      case "string_lit": return { tag: "string", val: expr.value };

      case "ident": return env.get(expr.name);

      case "array_lit": {
        const elements = expr.elements.map(e => this.evalExpr(e, env));
        return { tag: "array", val: elements };
      }

      case "tensor_lit": {
        const elements = expr.elements.map(e => asNum(this.evalExpr(e, env)));
        return { tag: "tensor", data: elements, shape: expr.shape };
      }

      case "unary": {
        const operand = this.evalExpr(expr.operand, env);
        if (expr.op === "-") return num(-asNum(operand));
        if (expr.op === "!") return { tag: "bool", val: !isTruthy(operand) };
        throw new RuntimeError(`알 수 없는 단항 연산자: ${expr.op}`);
      }

      case "binary": return this.evalBinary(expr.op, expr.left, expr.right, env);

      case "matmul": {
        const left = this.evalExpr(expr.left, env);
        const right = this.evalExpr(expr.right, env);
        return tensorMatmul(asTensor(left), asTensor(right));
      }

      case "transpose": {
        const operand = this.evalExpr(expr.operand, env);
        return tensorTranspose(asTensor(operand));
      }

      case "assign": {
        const val = this.evalExpr(expr.value, env);
        if (expr.target.kind === "ident") {
          env.assign(expr.target.name, val);
        } else if (expr.target.kind === "index") {
          const obj = this.evalExpr(expr.target.object, env);
          const idx = asNum(this.evalExpr(expr.target.index, env));
          if (obj.tag === "array") obj.val[idx] = val;
          else if (obj.tag === "tensor") obj.data[idx] = asNum(val);
          else throw new RuntimeError("인덱스 할당: 배열/텐서에만 가능");
        } else if (expr.target.kind === "field_access") {
          const obj = this.evalExpr(expr.target.object, env);
          if (obj.tag !== "array") throw new RuntimeError("필드 할당: 구조체에만 가능");
        }
        return val;
      }

      case "call": {
        const callee = this.evalExpr(expr.callee, env);
        const args = expr.args.map(a => this.evalExpr(a, env));
        return this.callFn(callee, args);
      }

      case "field_access": {
        const obj = this.evalExpr(expr.object, env);
        return this.getField(obj, expr.field, env);
      }

      case "index": {
        const obj = this.evalExpr(expr.object, env);
        const idx = asNum(this.evalExpr(expr.index, env));
        if (obj.tag === "array") return obj.val[idx] ?? { tag: "null" };
        if (obj.tag === "tensor") {
          // 2D tensor: 행 반환 → 1D tensor
          if (obj.shape.length === 2) {
            const [_, cols] = obj.shape;
            const row = obj.data.slice(idx * cols, (idx + 1) * cols);
            return { tag: "tensor", data: row, shape: [cols] };
          }
          return num(obj.data[idx]);
        }
        if (obj.tag === "string") return { tag: "string", val: obj.val[idx] };
        throw new RuntimeError(`인덱스: ${obj.tag}에 사용 불가`);
      }

      case "if_expr": {
        const cond = this.evalExpr(expr.condition, env);
        if (isTruthy(cond)) {
          let last: RuntimeValue = { tag: "null" };
          for (const e of expr.then) last = this.evalExpr(e, env);
          return last;
        } else {
          let last: RuntimeValue = { tag: "null" };
          for (const e of expr.else_) last = this.evalExpr(e, env);
          return last;
        }
      }

      case "fn_lit": {
        return {
          tag: "fn",
          params: expr.params.map(p => p.name),
          body: expr.body.kind === "block_expr" ? expr.body.stmts : [],
          closure: env,
        };
      }

      case "block_expr": {
        const blockEnv = new Env(env);
        let last: RuntimeValue = { tag: "null" };
        for (const s of expr.stmts) {
          const r = this.execStmt(s, blockEnv);
          if (r instanceof ReturnSignal) return r.value;
        }
        if (expr.expr) last = this.evalExpr(expr.expr, blockEnv);
        return last;
      }

      case "grad_block": {
        for (const s of expr.body) this.execStmt(s, new Env(env));
        return { tag: "null" };
      }

      case "struct_lit": {
        // struct를 array+키로 표현
        const fields: RuntimeValue[] = [];
        for (const f of expr.fields) fields.push(this.evalExpr(f.value, env));
        return { tag: "array", val: fields };
      }

      default:
        return { tag: "null" };
    }
  }

  private evalBinary(op: string, leftExpr: Expr, rightExpr: Expr, env: Env): RuntimeValue {
    const left = this.evalExpr(leftExpr, env);
    const right = this.evalExpr(rightExpr, env);

    // Tensor 원소별 연산
    if (left.tag === "tensor" && right.tag === "tensor") {
      return tensorElemwise(op, left, right);
    }
    if (left.tag === "tensor" && right.tag === "number") {
      return tensorScalar(op, left, right.val);
    }

    // autograd
    if (left.tag === "autograd" && right.tag === "autograd") {
      if (op === "+") return { tag: "autograd", val: left.val.add(right.val) };
      if (op === "*") return { tag: "autograd", val: left.val.mul(right.val) };
    }

    // 수치 연산
    if (op === "+") {
      if (left.tag === "string" || right.tag === "string") {
        return { tag: "string", val: this.display(left) + this.display(right) };
      }
      return num(asNum(left) + asNum(right));
    }
    if (op === "-") return num(asNum(left) - asNum(right));
    if (op === "*") return num(asNum(left) * asNum(right));
    if (op === "/") return num(asNum(left) / asNum(right));
    if (op === "%") return num(asNum(left) % asNum(right));

    // 비교
    if (op === "==") return { tag: "bool", val: runtimeEqual(left, right) };
    if (op === "!=") return { tag: "bool", val: !runtimeEqual(left, right) };
    if (op === "<")  return { tag: "bool", val: asNum(left) <  asNum(right) };
    if (op === ">")  return { tag: "bool", val: asNum(left) >  asNum(right) };
    if (op === "<=") return { tag: "bool", val: asNum(left) <= asNum(right) };
    if (op === ">=") return { tag: "bool", val: asNum(left) >= asNum(right) };

    // 논리
    if (op === "&&") return { tag: "bool", val: isTruthy(left) && isTruthy(right) };
    if (op === "||") return { tag: "bool", val: isTruthy(left) || isTruthy(right) };

    throw new RuntimeError(`알 수 없는 이항 연산자: ${op}`);
  }

  private getField(obj: RuntimeValue, field: string, env: Env): RuntimeValue {
    // TokenizerObject
    if (obj.tag === "array" && (obj as any).__type === "TokenizerObject") {
      const tok: CharTokenizer | BPETokenizer = (obj as any).__tok;
      if (field === "fit") return { tag: "builtin", fn: (text, vocabSize?) => {
        if (tok instanceof BPETokenizer) tok.fit(asString(text), vocabSize ? asNum(vocabSize) : 256);
        else tok.fit(asString(text));
        return { tag: "null" };
      }};
      if (field === "encode") return { tag: "builtin", fn: (text) => ({
        tag: "array", val: tok.encode(asString(text)).map(v => num(v))
      })};
      if (field === "decode") return { tag: "builtin", fn: (ids) => ({
        tag: "string", val: tok.decode(asArr(ids).map(v => asNum(v)))
      })};
      if (field === "vocabSize") return num(tok.vocabSize);
      throw new RuntimeError(`Tokenizer.${field} 없음`);
    }

    // GPTObject
    if (obj.tag === "array" && (obj as any).__type === "GPTObject") {
      const gpt: MiniGPT = (obj as any).__gpt;
      if (field === "forward") return { tag: "builtin", fn: (ids) => {
        const idArr = asArr(ids).map(v => asNum(v));
        const logits = gpt.forward(idArr);
        return { tag: "array", val: logits.map(row => ({
          tag: "array", val: row.map(v => ({ tag: "autograd", val: v }))
        }))};
      }};
      if (field === "predict") return { tag: "builtin", fn: (ids, temp?) => {
        const idArr = asArr(ids).map(v => asNum(v));
        return num(gpt.predict(idArr, temp ? asNum(temp) : 1.0));
      }};
      if (field === "generate") return { tag: "builtin", fn: (ids, maxNew, temp?) => {
        const idArr = asArr(ids).map(v => asNum(v));
        const result = gpt.generate(idArr, asNum(maxNew), temp ? asNum(temp) : 1.0);
        return { tag: "array", val: result.map(v => num(v)) };
      }};
      if (field === "params") return { tag: "builtin", fn: () => ({
        tag: "array", val: gpt.params().map(v => ({ tag: "autograd", val: v }))
      })};
      if (field === "train") return { tag: "builtin", fn: (trainIds, epochs, lr?) => {
        const ids = asArr(trainIds).map(v => asNum(v));
        const losses = trainLM(gpt, ids, {
          epochs: asNum(epochs),
          lr: lr ? asNum(lr) : 1e-3,
          seqLen: Math.min(16, Math.floor(ids.length / 2)),
          logEvery: Math.max(1, Math.floor(asNum(epochs) / 5)),
          verbose: true,
        });
        return { tag: "array", val: losses.map(v => num(v)) };
      }};
      throw new RuntimeError(`GPT.${field} 없음`);
    }

    // ModuleObject (Linear, ReLU, Sequential 등)
    if (obj.tag === "array" && (obj as any).__type === "ModuleObject") {
      const mod: Module = (obj as any).__module;
      if (field === "forward") return { tag: "builtin", fn: (x) => {
        const input = asArr(x).map(v => {
          if (v.tag === "autograd") return v.val;
          return new AutoValue(asNum(v));
        });
        const out = mod.forward(input);
        return { tag: "array", val: out.map(v => ({ tag: "autograd", val: v })) };
      }};
      if (field === "params") return { tag: "builtin", fn: () => ({
        tag: "array", val: mod.params().map(v => ({ tag: "autograd", val: v }))
      })};
      if (field === "name") return { tag: "string", val: mod.name };
      throw new RuntimeError(`Module.${field} 없음`);
    }

    // MLPObject / AdamObject (struct로 포장됨)
    if (obj.tag === "array" && (obj as any).__type === "MLPObject") {
      const model: MLP = (obj as any).__model;
      if (field === "forward" || field === "call") {
        return { tag: "builtin", fn: (x) => {
          const input = asTensor(x).data;
          const out = model.forward(input);
          return { tag: "array", val: out.map(v => ({ tag: "autograd", val: v })) };
        }};
      }
      if (field === "params") return { tag: "builtin", fn: () => ({
        tag: "array", val: model.params().map(v => ({ tag: "autograd", val: v }))
      })};
      throw new RuntimeError(`MLP.${field} 없음`);
    }
    if (obj.tag === "array" && (obj as any).__type === "AdamObject") {
      const optim: Adam = (obj as any).__optim;
      if (field === "step") return { tag: "builtin", fn: (paramsArr) => {
        const params = asArr(paramsArr).map(v => {
          if (v.tag === "autograd") return v.val;
          throw new RuntimeError("Adam.step: AutoGrad 파라미터 필요");
        });
        optim.step(params);
        return { tag: "null" };
      }};
      if (field === "zeroGrad") return { tag: "builtin", fn: (paramsArr) => {
        const params = asArr(paramsArr).map(v => {
          if (v.tag === "autograd") return v.val;
          throw new RuntimeError("Adam.zeroGrad: AutoGrad 파라미터 필요");
        });
        optim.zeroGrad(params);
        return { tag: "null" };
      }};
      throw new RuntimeError(`Adam.${field} 없음`);
    }
    if (obj.tag === "array" && (obj as any).__type === "SgdObject") {
      const optim: SGD = (obj as any).__optim;
      if (field === "step") return { tag: "builtin", fn: (paramsArr) => {
        const params = asArr(paramsArr).map(v => {
          if (v.tag === "autograd") return v.val;
          throw new RuntimeError("SGD.step: AutoGrad 파라미터 필요");
        });
        optim.step(params);
        return { tag: "null" };
      }};
      if (field === "zeroGrad") return { tag: "builtin", fn: (paramsArr) => {
        const params = asArr(paramsArr).map(v => {
          if (v.tag === "autograd") return v.val;
          throw new RuntimeError("SGD.zeroGrad: AutoGrad 파라미터 필요");
        });
        optim.zeroGrad(params);
        return { tag: "null" };
      }};
      throw new RuntimeError(`SGD.${field} 없음`);
    }

    // autograd 메서드
    if (obj.tag === "autograd") {
      if (field === "data") return num(obj.val.data);
      if (field === "grad") return num(obj.val.grad);
      if (field === "backward") return { tag: "builtin", fn: () => {
        obj.val.backward();
        return { tag: "null" };
      }};
    }

    // tensor 속성
    if (obj.tag === "tensor") {
      if (field === "shape") return { tag: "array", val: obj.shape.map(s => num(s)) };
      if (field === "T") return tensorTranspose(obj);
      if (field === "data") return { tag: "array", val: obj.data.map(v => num(v)) };
      if (field === "backward") return { tag: "builtin", fn: () => { return { tag: "null" }; }};
    }

    // array 메서드
    if (obj.tag === "array") {
      if (field === "length") return num(obj.val.length);
      if (field === "push") return { tag: "builtin", fn: (v) => { obj.val.push(v); return { tag: "null" }; }};
      if (field === "pop")  return { tag: "builtin", fn: () => obj.val.pop() ?? { tag: "null" }};
      if (field === "map")  return { tag: "builtin", fn: (fn) => ({ tag: "array", val: obj.val.map(v => this.callFn(fn, [v])) })};
      if (field === "filter") return { tag: "builtin", fn: (fn) => ({ tag: "array", val: obj.val.filter(v => isTruthy(this.callFn(fn, [v]))) })};
      if (field === "forEach") return { tag: "builtin", fn: (fn) => { obj.val.forEach((v, i) => this.callFn(fn, [v, num(i)])); return { tag: "null" }; }};
      if (field === "reduce") return { tag: "builtin", fn: (fn, init) => obj.val.reduce((acc, v) => this.callFn(fn, [acc, v]), init)};
      if (field === "join") return { tag: "builtin", fn: (sep) => ({ tag: "string", val: obj.val.map(v => this.display(v)).join(sep.tag === "string" ? sep.val : ",") })};
      if (field === "slice") return { tag: "builtin", fn: (s, e) => ({ tag: "array", val: obj.val.slice(asNum(s), e ? asNum(e) : undefined) })};
      if (field === "indexOf") return { tag: "builtin", fn: (v) => num(obj.val.findIndex(x => runtimeEqual(x, v)))};
    }

    // string 메서드
    if (obj.tag === "string") {
      if (field === "length") return num(obj.val.length);
      if (field === "split") return { tag: "builtin", fn: (sep) => ({
        tag: "array",
        val: obj.val.split(sep.tag === "string" ? sep.val : "").map(s => ({ tag: "string", val: s }))
      })};
      if (field === "trim") return { tag: "builtin", fn: () => ({ tag: "string", val: obj.val.trim() })};
      if (field === "toUpperCase") return { tag: "builtin", fn: () => ({ tag: "string", val: obj.val.toUpperCase() })};
      if (field === "toLowerCase") return { tag: "builtin", fn: () => ({ tag: "string", val: obj.val.toLowerCase() })};
    }

    throw new RuntimeError(`필드 없음: ${obj.tag}.${field}`);
  }

  callFn(callee: RuntimeValue, args: RuntimeValue[]): RuntimeValue {
    if (callee.tag === "builtin") return callee.fn(...args);
    // ModuleObject 직접 호출
    if (callee.tag === "array" && (callee as any).__type === "ModuleObject") {
      const mod: Module = (callee as any).__module;
      const input = asArr(args[0]).map(v => {
        if (v.tag === "autograd") return v.val;
        return new AutoValue(asNum(v));
      });
      const out = mod.forward(input);
      return { tag: "array", val: out.map(v => ({ tag: "autograd", val: v })) };
    }
    // MLPObject 직접 호출
    if (callee.tag === "array" && (callee as any).__type === "MLPObject") {
      const model: MLP = (callee as any).__model;
      const input = asTensor(args[0]).data;
      const out = model.forward(input);
      return { tag: "array", val: out.map(v => ({ tag: "autograd", val: v })) };
    }
    if (callee.tag === "fn") {
      const fnEnv = new Env(callee.closure);
      for (let i = 0; i < callee.params.length; i++) {
        fnEnv.set(callee.params[i], args[i] ?? { tag: "null" });
      }
      const result = this.execBlock(callee.body, fnEnv);
      if (result instanceof ReturnSignal) return result.value;
      return result as RuntimeValue;
    }
    throw new RuntimeError(`호출 불가: ${callee.tag}`);
  }

  display(val: RuntimeValue): string {
    if (val.tag === "number") return String(val.val);
    if (val.tag === "bool")   return String(val.val);
    if (val.tag === "string") return val.val;
    if (val.tag === "null")   return "null";
    if (val.tag === "array")  return `[${val.val.map(v => this.display(v)).join(", ")}]`;
    if (val.tag === "tensor") {
      if (val.shape.length === 1) return `Tensor[${val.shape[0]}](${val.data.map(v => v.toFixed(4)).join(", ")})`;
      if (val.shape.length === 2) {
        const [rows, cols] = val.shape;
        const rows_str = Array.from({ length: rows }, (_, i) =>
          `  [${val.data.slice(i * cols, (i + 1) * cols).map(v => v.toFixed(4)).join(", ")}]`
        ).join("\n");
        return `Tensor[${rows}×${cols}]:\n${rows_str}`;
      }
      return `Tensor${JSON.stringify(val.shape)}`;
    }
    if (val.tag === "autograd") return `AutoGrad(${val.val.data.toFixed(6)})`;
    if (val.tag === "fn")      return "<fn>";
    if (val.tag === "builtin") return "<builtin>";
    if (val.tag === "native")  return `<native:${(val.val as any)?.constructor?.name ?? "object"}>`;
    const anyVal = val as any;
    if (anyVal.__type === "MLPObject")       return `<MLP>`;
    if (anyVal.__type === "ModuleObject")   return `<${anyVal.__name}>`;
    if (anyVal.__type === "AdamObject")     return `<Adam>`;
    if (anyVal.__type === "SgdObject")      return `<SGD>`;
    if (anyVal.__type === "TokenizerObject") return `<Tokenizer vocab=${anyVal.__tok.vocabSize}>`;
    if (anyVal.__type === "GPTObject")      return `<MiniGPT d=${anyVal.__gpt.config.dModel} layers=${anyVal.__gpt.config.numLayers}>`;
    return "?";
  }
}

// ============================================================
// 헬퍼 함수
// ============================================================

function num(v: number): RuntimeValue { return { tag: "number", val: v }; }

function asNum(v: RuntimeValue): number {
  if (v.tag === "number") return v.val;
  if (v.tag === "bool")   return v.val ? 1 : 0;
  if (v.tag === "autograd") return v.val.data;
  throw new RuntimeError(`숫자 필요 (got ${v.tag})`);
}

function asStr(v: RuntimeValue): string {
  if (v.tag === "string") return v.val;
  if (v.tag === "number") return String(v.val);
  if (v.tag === "bool")   return String(v.val);
  if (v.tag === "null")   return "";
  throw new RuntimeError(`문자열 필요 (got ${v.tag})`);
}

function asArr(v: RuntimeValue): RuntimeValue[] {
  if (v.tag === "array") return v.val;
  if (v.tag === "tensor") return v.data.map(d => num(d));
  throw new RuntimeError(`배열 필요 (got ${v.tag})`);
}

function asTensor(v: RuntimeValue): { data: number[]; shape: number[] } {
  if (v.tag === "tensor") return v;
  if (v.tag === "array") {
    const data = v.val.map(x => asNum(x));
    return { data, shape: [data.length] };
  }
  if (v.tag === "number") return { data: [v.val], shape: [1] };
  throw new RuntimeError(`텐서 필요 (got ${v.tag})`);
}

function asAV(v: RuntimeValue): AutoValue {
  if (v.tag === "autograd") return v.val;
  if (v.tag === "number") return new AutoValue(v.val);
  throw new RuntimeError(`autograd Value 필요 (got ${v.tag})`);
}

function isTruthy(v: RuntimeValue): boolean {
  if (v.tag === "bool")   return v.val;
  if (v.tag === "number") return v.val !== 0;
  if (v.tag === "null")   return false;
  return true;
}

function runtimeEqual(a: RuntimeValue, b: RuntimeValue): boolean {
  if (a.tag !== b.tag) return false;
  if (a.tag === "number" && b.tag === "number") return a.val === b.val;
  if (a.tag === "bool"   && b.tag === "bool")   return a.val === b.val;
  if (a.tag === "string" && b.tag === "string") return a.val === b.val;
  if (a.tag === "null"   && b.tag === "null")   return true;
  return false;
}

function builtin1(fn: (a: RuntimeValue) => RuntimeValue): RuntimeValue {
  return { tag: "builtin", fn: (a) => fn(a) };
}
function builtin2(fn: (a: RuntimeValue, b: RuntimeValue) => RuntimeValue): RuntimeValue {
  return { tag: "builtin", fn: (a, b) => fn(a, b) };
}

// ============================================================
// Tensor 연산
// ============================================================

function tensorMatmul(
  a: { data: number[]; shape: number[] },
  b: { data: number[]; shape: number[] }
): RuntimeValue {
  if (a.shape.length !== 2 || b.shape.length !== 2) {
    throw new RuntimeError(`matmul: 2D 텐서 필요 (got ${a.shape} @ ${b.shape})`);
  }
  const [N, M1] = a.shape;
  const [M2, K] = b.shape;
  if (M1 !== M2) throw new RuntimeError(`matmul shape 불일치: [${N},${M1}] @ [${M2},${K}]`);

  const result = new Array(N * K).fill(0);
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < K; j++) {
      let sum = 0;
      for (let k = 0; k < M1; k++) {
        sum += a.data[i * M1 + k] * b.data[k * K + j];
      }
      result[i * K + j] = sum;
    }
  }
  return { tag: "tensor", data: result, shape: [N, K] };
}

function tensorTranspose(t: { data: number[]; shape: number[] }): RuntimeValue {
  if (t.shape.length !== 2) throw new RuntimeError(".T: 2D 텐서 필요");
  const [rows, cols] = t.shape;
  const result = new Array(rows * cols);
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      result[j * rows + i] = t.data[i * cols + j];
    }
  }
  return { tag: "tensor", data: result, shape: [cols, rows] };
}

function tensorElemwise(op: string, a: { data: number[]; shape: number[] }, b: { data: number[]; shape: number[] }): RuntimeValue {
  if (a.data.length !== b.data.length) throw new RuntimeError(`원소별 연산 shape 불일치`);
  let fn: (x: number, y: number) => number;
  if (op === "+") fn = (x, y) => x + y;
  else if (op === "-") fn = (x, y) => x - y;
  else if (op === "*") fn = (x, y) => x * y;
  else if (op === "/") fn = (x, y) => x / y;
  else throw new RuntimeError(`텐서 연산 미지원: ${op}`);
  return { tag: "tensor", data: a.data.map((v, i) => fn(v, b.data[i])), shape: a.shape.slice() };
}

function tensorScalar(op: string, t: { data: number[]; shape: number[] }, s: number): RuntimeValue {
  let fn: (x: number) => number;
  if (op === "+") fn = x => x + s;
  else if (op === "-") fn = x => x - s;
  else if (op === "*") fn = x => x * s;
  else if (op === "/") fn = x => x / s;
  else throw new RuntimeError(`텐서 스칼라 연산 미지원: ${op}`);
  return { tag: "tensor", data: t.data.map(fn), shape: t.shape.slice() };
}

function to2DArray(v: RuntimeValue): number[][] {
  // array of arrays
  if (v.tag === "array") {
    const first = v.val[0];
    if (!first) return [];
    if (first.tag === "array") return v.val.map(row => asArr(row).map(x => asNum(x)));
    // flat array → 1 row
    return [v.val.map(x => asNum(x))];
  }
  // 2D tensor → rows
  if (v.tag === "tensor" && v.shape.length === 2) {
    const [rows, cols] = v.shape;
    return Array.from({ length: rows }, (_, i) => v.data.slice(i * cols, (i + 1) * cols));
  }
  throw new RuntimeError(`2D 배열 필요 (got ${v.tag})`);
}

function toAutoValues(v: RuntimeValue): AutoValue[] {
  if (v.tag === "autograd") return [v.val];
  if (v.tag === "array") return v.val.map(x => {
    if (x.tag === "autograd") return x.val;
    return new AutoValue(asNum(x));
  });
  if (v.tag === "number") return [new AutoValue(v.val)];
  throw new RuntimeError(`AutoValue 변환 실패: ${v.tag}`);
}

function makeModuleObject(mod: Module, name: string): RuntimeValue {
  const obj: any = { tag: "array", val: [], __type: "ModuleObject", __module: mod, __name: name };
  return obj as RuntimeValue;
}

function makeMlpObject(model: MLP): RuntimeValue {
  const obj: any = { tag: "array", val: [], __type: "MLPObject", __model: model };
  return obj as RuntimeValue;
}

function makeAdamObject(optim: Adam): RuntimeValue {
  const obj: any = { tag: "array", val: [], __type: "AdamObject", __optim: optim };
  return obj as RuntimeValue;
}

function makeSgdObject(optim: SGD): RuntimeValue {
  const obj: any = { tag: "array", val: [], __type: "SgdObject", __optim: optim };
  return obj as RuntimeValue;
}

function makeTokenizerObject(tok: CharTokenizer | BPETokenizer): RuntimeValue {
  const obj: any = { tag: "array", val: [], __type: "TokenizerObject", __tok: tok };
  return obj as RuntimeValue;
}

function makeGPTObject(gpt: MiniGPT): RuntimeValue {
  const obj: any = { tag: "array", val: [], __type: "GPTObject", __gpt: gpt };
  return obj as RuntimeValue;
}

function asString(v: RuntimeValue): string {
  if (v.tag === "string") return v.val;
  throw new RuntimeError(`문자열 필요 (got ${v.tag})`);
}

function matchPattern(pattern: any, value: RuntimeValue): Record<string, RuntimeValue> | null {
  if (pattern.kind === "wildcard") return {};
  if (pattern.kind === "ident") return { [pattern.name]: value };
  if (pattern.kind === "literal") {
    const lit = pattern.value;
    if (lit.kind === "int_lit" && value.tag === "number" && value.val === lit.value) return {};
    if (lit.kind === "float_lit" && value.tag === "number" && value.val === lit.value) return {};
    if (lit.kind === "bool_lit" && value.tag === "bool" && value.val === lit.value) return {};
    if (lit.kind === "string_lit" && value.tag === "string" && value.val === lit.value) return {};
  }
  return null;
}

