// FreeLang v8 ML — GPT Cross-Entropy Loss (Phase L)
//
// 입력: logits [vocab_size] (1D), target_id (정수)
// 출력: loss (scalar)
//
// CE loss = -log(softmax(logits)[target_id])
//         = -logits[target_id] + log(sum(exp(logits - max)))

// ─── cross-entropy loss ──────────────────────────────────────
// ce_loss(logits, target_id) → scalar
//   logits: 1D tensor [vocab_size]
//   target_id: 정수 (정답 클래스 인덱스)

fn ce_loss(logits: i32, target_id: i32) -> i32 {
  return t_ce_loss(logits, target_id)
}

// ─── sequence CE loss ────────────────────────────────────────
// seq_ce_loss(logits_2d, target_ids, seq_len, vocab_size)
//   → scalar (평균 loss, 전체 시퀀스)
//
// logits_2d: [seq_len, vocab_size]
// target_ids: [seq_len] (다음 토큰 정답)

fn seq_ce_loss(logits_2d: i32, target_ids: i32, seq_len: i32, vocab_size: i32) -> i32 {
  let total_loss = 0.0
  let i = 0
  for i in range(seq_len) {
    let logits_row = t_row(logits_2d, i)
    let tid = int(target_ids[i])
    let loss = t_ce_loss(logits_row, tid)
    total_loss = total_loss + loss
  }
  return total_loss / float(seq_len)
}

// ─── perplexity ──────────────────────────────────────────────
// perplexity(avg_loss) → scalar
//   PPL = exp(avg_ce_loss)

fn perplexity(avg_loss: i32) -> i32 {
