// FreeLang v8 ML — Adam Optimizer (Phase L)
//
// Adam: Adaptive Moment Estimation
//
// 상태: m (1st moment), v (2nd moment), t (step count)
// 업데이트:
//   g_t = gradient
//   m_t = β1 * m_{t-1} + (1-β1) * g_t
//   v_t = β2 * v_{t-1} + (1-β2) * g_t²
//   m̂_t = m_t / (1 - β1^t)   bias correction
//   v̂_t = v_t / (1 - β2^t)
//   w_t = w_{t-1} - lr * m̂_t / (sqrt(v̂_t) + ε)
//
// FL8 제약: struct 없음 → [m, v, step] 배열 기반 상태

// ─── Adam 상태 초기화 ────────────────────────────────────────
// make_adam_state(param) → [m, v, step]
//   m, v: param과 같은 shape의 0 텐서
//   step: 0

fn make_adam_state(param: i32) -> i32 {
  let state = []
  push(state, t_zeros_like(param))  // m
  push(state, t_zeros_like(param))  // v
  push(state, 0)                    // step
  return state
}

// ─── Adam 단일 파라미터 업데이트 ────────────────────────────
// adam_update(param, grad, state, lr, b1, b2, eps)
//   → updated param (in-place + return)
//   state: [m, v, step] (수정됨)

fn adam_update(param: i32, grad: i32, state: i32,
               lr: i32, b1: i32, b2: i32, eps: i32) -> i32 {
  let m    = state[0]
  let v    = state[1]
  let step = state[2] + 1
  state[2] = step

  // m = b1*m + (1-b1)*grad
  let m_b1  = t_scale(m, b1)
  let g_mb1 = t_scale(grad, 1.0 - b1)
  let m_new = t_add(m_b1, g_mb1)
  state[0]  = m_new

  // v = b2*v + (1-b2)*grad^2
  let g2    = t_pow2(grad)
  let v_b2  = t_scale(v, b2)
  let g_vb2 = t_scale(g2, 1.0 - b2)
  let v_new = t_add(v_b2, g_vb2)
  state[1]  = v_new

  // bias correction
  let bc1   = 1.0 - pow(b1, float(step))
  let bc2   = 1.0 - pow(b2, float(step))
  let m_hat = t_scale(m_new, 1.0 / bc1)
  let v_hat = t_scale(v_new, 1.0 / bc2)

  // w = w - lr * m_hat / (sqrt(v_hat) + eps)
  let v_sqrt  = t_sqrt(v_hat)
  let denom   = t_scale(v_sqrt, 1.0)
  let i = 0
  let n = t_rows(param) * t_cols(param)
  // t_sqrt에 eps 추가 → t_add with eps tensor
  let eps_t   = t_ones_like(v_sqrt)
  let eps_sc  = t_scale(eps_t, eps)
  let denom2  = t_add(denom, eps_sc)
  let step_t  = t_div(m_hat, denom2)
  let delta   = t_scale(step_t, lr)
  let updated = t_sub(param, delta)
  return updated
}

// ─── 다중 파라미터 Adam 업데이트 ────────────────────────────
// adam_step(params, grads, states, lr, b1, b2, eps)
//   params, grads, states: 같은 길이 배열
//   → params 원소를 업데이트된 값으로 교체

fn adam_step(params: i32, grads: i32, states: i32,
             lr: i32, b1: i32, b2: i32, eps: i32) -> i32 {
  let n = len(params)
  let i = 0
  for i in range(n) {
    let updated = adam_update(params[i], grads[i], states[i],
                              lr, b1, b2, eps)
    params[i] = updated
  }
  return params
}

// ─── 검증 ────────────────────────────────────────────────────

print("=== gpt_adam.fl8 ===")

let d = 4

// 임의 파라미터 (1D)
let param = reshape(randn(d), d)
print("param before:", t_sum(param))

// 상태 초기화
let state = make_adam_state(param)
print("state len:", len(state))

// 기울기 (모두 0.1)
let grad1 = reshape(ones(d), d)
let grad = t_scale(grad1, 0.1)

// Adam 업데이트 3회
let lr  = 0.01
let b1  = 0.9
let b2  = 0.999
let eps = 0.00000001

let p1 = adam_update(param, grad, state, lr, b1, b2, eps)
let p2 = adam_update(p1,    grad, state, lr, b1, b2, eps)
let p3 = adam_update(p2,    grad, state, lr, b1, b2, eps)
print("param after 3 steps sum:", t_sum(p3))
print("step count:", state[2])

// 파라미터 감소 여부 확인 (gradient 방향으로 감소)
let diff = t_sub(p3, param)
let diff_sum = t_sum(diff)
print("param change (should be negative):", diff_sum)

print("PASS: gpt_adam.fl8")

