// FreeLang v8 ML — GPT Train Step (Phase L)
//
// 수치 미분(finite difference)으로 gradient 계산:
//   ∂L/∂w_i ≈ (L(w+ε*e_i) - L(w-ε*e_i)) / (2ε)
//
// 소규모 모델(d=4, ffn=8, layers=1, vocab=8)로 1 step 실증
//
// ── 인라인 의존 함수 (import 없음) ──────────────────────────

fn embed_seq(table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let out = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(table, int(ids[i]))
    t_set_row(out, i, row)
  }
  return out
}

fn embed_forward(tok_table: i32, pos_table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let tok_e = embed_seq(tok_table, ids, seq_len, d_model)
  let pos_e = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(pos_table, i)
    t_set_row(pos_e, i, row)
  }
  return t_add(tok_e, pos_e)
}

fn linear_fwd(x: i32, W: i32, b: i32, seq_len: i32, out_dim: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(out, i)
    let nr = t_add(row, b)
    t_set_row(out, i, nr)
  }
  return out
}

fn row_softmax(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) {
    let row = t_row(t, i)
    let sm = t_softmax(row)
    t_set_row(out, i, sm)
  }
  return out
}

fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32,
            seq_len: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, seq_len, d)
  let K = linear_fwd(x, Wk, bk, seq_len, d)
  let V = linear_fwd(x, Wv, bv, seq_len, d)
  let Kt = transpose(K)
  let scores = matmul(Q, Kt)
  let scale = 1.0 / sqrt(float(d))
  let sm = t_scale(scores, scale)
  let mask = t_causal_mask(seq_len)
  let sm2 = t_add(sm, mask)
  let attn_w = row_softmax(sm2, seq_len, seq_len)
  let ctx = matmul(attn_w, V)
  return linear_fwd(ctx, Wo, bo, seq_len, d)
}

fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32,
           seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let h = matmul(x, W1)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(h, i)
    t_set_row(h, i, t_add(row, b1))
  }
  let h_act = t_gelu(h)
  let out = matmul(h_act, W2)
  for i in range(seq_len) {
    let row = t_row(out, i)
    t_set_row(out, i, t_add(row, b2))
  }
  return out
}

fn row_layer_norm(x: i32, scale: i32, bias: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(x, i)
    let nr = t_layer_norm(row, scale, bias, 0.00001)
    t_set_row(out, i, nr)
  }
  return out
}

fn block_fwd(x: i32,
             Wq: i32, Wk: i32, Wv: i32, Wo: i32,
             bq: i32, bk: i32, bv: i32, bo: i32,
             W1: i32, b1: i32, W2: i32, b2: i32,
             ln1s: i32, ln1b: i32, ln2s: i32, ln2b: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let x1 = row_layer_norm(x, ln1s, ln1b, seq_len, d)
  let ao = attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, seq_len, d)
  let x2 = t_add(x, ao)
  let x3 = row_layer_norm(x2, ln2s, ln2b, seq_len, d)
  let fo = ffn_fwd(x3, W1, b1, W2, b2, seq_len, d, ffn_dim)
  return t_add(x2, fo)
}

fn layer_fwd(x: i32, params: i32, li: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let base = li * 16
  return block_fwd(x,
    params[base+0], params[base+1], params[base+2], params[base+3],
    params[base+4], params[base+5], params[base+6], params[base+7],
    params[base+8], params[base+9], params[base+10], params[base+11],
    params[base+12], params[base+13], params[base+14], params[base+15],
    seq_len, d, ffn_dim)
}

// ─── 미니 GPT forward (소규모, 학습용) ──────────────────────
// mini_forward(tok_t, pos_t, params, fls, flb, lmh, lmb,
//              ids, seq_len, d, ffn, vocab) → logits [vocab]

fn mini_forward(tok_t: i32, pos_t: i32, params: i32,
                fls: i32, flb: i32, lmh: i32, lmb: i32,
                ids: i32, seq_len: i32, d: i32, ffn: i32, vocab: i32) -> i32 {
  let x = embed_forward(tok_t, pos_t, ids, seq_len, d)
  x = layer_fwd(x, params, 0, seq_len, d, ffn)
  let last = t_row(x, seq_len - 1)
  let ln_out = t_layer_norm(last, fls, flb, 0.00001)
  let ln_2d = reshape(ln_out, 1, d)
  let logits_2d = matmul(ln_2d, lmh)
  let logits = t_row(logits_2d, 0)
  return t_add(logits, lmb)
}

// ─── 수치 미분으로 1D 텐서 gradient 계산 ────────────────────
// numerical_grad_1d(param_1d, forward_fn, eps) → grad tensor
// 여기서는 lm_bias만 계산 (가장 단순한 1D 파라미터)

fn compute_loss(tok_t: i32, pos_t: i32, params: i32,
                fls: i32, flb: i32, lmh: i32, lmb: i32,
                ids: i32, target: i32,
                seq_len: i32, d: i32, ffn: i32, vocab: i32) -> i32 {
  let logits = mini_forward(tok_t, pos_t, params, fls, flb, lmh, lmb,
                             ids, seq_len, d, ffn, vocab)
  return t_ce_loss(logits, target)
}

fn numerical_grad_lmb(tok_t: i32, pos_t: i32, params: i32,
                       fls: i32, flb: i32, lmh: i32, lmb: i32,
                       ids: i32, target: i32,
                       seq_len: i32, d: i32, ffn: i32, vocab: i32,
                       fd_eps: i32) -> i32 {
  let grad = t_zeros_like(lmb)
  let i = 0
  for i in range(vocab) {
    // w+ε
    let lmb_plus = t_copy(lmb)
    let v_plus = t_get(lmb_plus, i)
    t_set(lmb_plus, i, v_plus + fd_eps)
    let loss_plus = compute_loss(tok_t, pos_t, params, fls, flb, lmh, lmb_plus,
                                  ids, target, seq_len, d, ffn, vocab)
    // w-ε
    let lmb_minus = t_copy(lmb)
    let v_minus = t_get(lmb_minus, i)
    t_set(lmb_minus, i, v_minus - fd_eps)
    let loss_minus = compute_loss(tok_t, pos_t, params, fls, flb, lmh, lmb_minus,
                                   ids, target, seq_len, d, ffn, vocab)
    // 중앙 차분
    let g = (loss_plus - loss_minus) / (2.0 * fd_eps)
    t_set(grad, i, g)
  }
  return grad
}

// ─── Adam 상태 초기화 ────────────────────────────────────────
fn make_adam_state(param: i32) -> i32 {
  let state = []
  push(state, t_zeros_like(param))
  push(state, t_zeros_like(param))
  push(state, 0)
  return state
}

fn adam_update(param: i32, grad: i32, state: i32,
               lr: i32, b1: i32, b2: i32, eps: i32) -> i32 {
  let m    = state[0]
  let v    = state[1]
  let step = state[2] + 1
  state[2] = step

  let m_new = t_add(t_scale(m, b1), t_scale(grad, 1.0 - b1))
  state[0]  = m_new
  let v_new = t_add(t_scale(v, b2), t_scale(t_pow2(grad), 1.0 - b2))
  state[1]  = v_new

  let bc1   = 1.0 - pow(b1, float(step))
  let bc2   = 1.0 - pow(b2, float(step))
  let m_hat = t_scale(m_new, 1.0 / bc1)
  let v_hat = t_scale(v_new, 1.0 / bc2)

  let denom = t_add(t_sqrt(v_hat), t_scale(t_ones_like(v_hat), eps))
  let delta = t_scale(t_div(m_hat, denom), lr)
  return t_sub(param, delta)
}

// ─── 검증 ────────────────────────────────────────────────────

print("=== gpt_train_step.fl8 ===")

