push(lp, reshape(zeros(d), d))  // bq
push(lp, reshape(zeros(d), d))  // bk
push(lp, reshape(zeros(d), d))  // bv
push(lp, reshape(zeros(d), d))  // bo
push(lp, randn(d, ffn))         // W1
