let adam_st = make_adam_state(lmb)
let lr  = 0.01
let b1  = 0.9
let b2  = 0.999
let eps = 0.00000001

let lmb1 = adam_update(lmb, grad_lmb, adam_st, lr, b1, b2, eps)

