  t_set(lmb_p, k, t_get(lmb_p, k) + fd_eps)
  let lp = simple_forward(tok_t, pos_t, lmh, lmb_p, ids, seq_len, d, vocab)
  let llp = t_ce_loss(lp, target)

  let lmb_m = t_copy(lmb)
  t_set(lmb_m, k, t_get(lmb_m, k) - fd_eps)
  let lm = simple_forward(tok_t, pos_t, lmh, lmb_m, ids, seq_len, d, vocab)
  let llm = t_ce_loss(lm, target)

  t_set(grad_b, k, (llp - llm) / (2.0 * fd_eps))
}

// Adam 업데이트
let m = t_zeros_like(lmb)
let v = t_zeros_like(lmb)
let step = 1
let lr = 0.1
let b1 = 0.9
let b2 = 0.999
let eps = 0.00000001

let m_new = t_add(t_scale(m, b1), t_scale(grad_b, 1.0 - b1))
let v_new = t_add(t_scale(v, b2), t_scale(t_pow2(grad_b), 1.0 - b2))
let bc1 = 1.0 - pow(b1, 1.0)
let bc2 = 1.0 - pow(b2, 1.0)
let m_hat = t_scale(m_new, 1.0 / bc1)
let v_hat = t_scale(v_new, 1.0 / bc2)
let denom = t_add(t_sqrt(v_hat), t_scale(t_ones_like(v_hat), eps))
let delta = t_scale(t_div(m_hat, denom), lr)
let lmb1 = t_sub(lmb, delta)

let logits1 = simple_forward(tok_t, pos_t, lmh, lmb1, ids, seq_len, d, vocab)
let loss1 = t_ce_loss(logits1, target)
loss1 < loss0
`);
  expect(r.val, 1, "loss decreases after adam step");
});

test("수치 미분 gradient: 합 방향 검증", () => {
