test("t_ce_loss 감소: 1 Adam step 후 loss < before", () => {
  // lm_bias에 대해 수치 미분 + Adam 1 step → loss 감소 확인
  // (간소화 버전: lm_bias만 업데이트)
  const r = runFL8(`
let vocab = 6
let d = 4
let seq_len = 2
let ffn = 8

// 간단한 모델 파라미터 (랜덤)
let tok_t = randn(vocab, d)
let pos_t = randn(seq_len, d)
let lmh   = randn(d, vocab)
let lmb   = reshape(zeros(vocab), vocab)

// embedding만 하는 단순 forward
fn simple_forward(tok_t: i32, pos_t: i32, lmh: i32, lmb: i32,
                  ids: i32, seq_len: i32, d: i32, vocab: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    let tok_row = t_row(tok_t, int(ids[i]))
    let pos_row = t_row(pos_t, i)
    t_set_row(out, i, t_add(tok_row, pos_row))
  }
  let last = t_row(out, seq_len - 1)
  let ln_2d = reshape(last, 1, d)
  let logits_2d = matmul(ln_2d, lmh)
  let logits = t_row(logits_2d, 0)
  return t_add(logits, lmb)
}

let ids = [1, 3]
let target = 4

let logits0 = simple_forward(tok_t, pos_t, lmh, lmb, ids, seq_len, d, vocab)
let loss0 = t_ce_loss(logits0, target)

// lmb 수치 미분
let fd_eps = 0.001
let grad_b = reshape(zeros(vocab), vocab)
let k = 0
for k in range(vocab) {
  let lmb_p = t_copy(lmb)
  t_set(lmb_p, k, t_get(lmb_p, k) + fd_eps)
  let lp = simple_forward(tok_t, pos_t, lmh, lmb_p, ids, seq_len, d, vocab)
  let llp = t_ce_loss(lp, target)

  let lmb_m = t_copy(lmb)
  t_set(lmb_m, k, t_get(lmb_m, k) - fd_eps)
  let lm = simple_forward(tok_t, pos_t, lmh, lmb_m, ids, seq_len, d, vocab)
  let llm = t_ce_loss(lm, target)

  t_set(grad_b, k, (llp - llm) / (2.0 * fd_eps))
}

// Adam 업데이트
let m = t_zeros_like(lmb)
let v = t_zeros_like(lmb)
let step = 1
let lr = 0.1
let b1 = 0.9
let b2 = 0.999
let eps = 0.00000001

let m_new = t_add(t_scale(m, b1), t_scale(grad_b, 1.0 - b1))
let v_new = t_add(t_scale(v, b2), t_scale(t_pow2(grad_b), 1.0 - b2))
let bc1 = 1.0 - pow(b1, 1.0)
let bc2 = 1.0 - pow(b2, 1.0)
let m_hat = t_scale(m_new, 1.0 / bc1)
let v_hat = t_scale(v_new, 1.0 / bc2)
let denom = t_add(t_sqrt(v_hat), t_scale(t_ones_like(v_hat), eps))
let delta = t_scale(t_div(m_hat, denom), lr)
let lmb1 = t_sub(lmb, delta)

let logits1 = simple_forward(tok_t, pos_t, lmh, lmb1, ids, seq_len, d, vocab)
let loss1 = t_ce_loss(logits1, target)
loss1 < loss0
`);
  expect(r.val, 1, "loss decreases after adam step");
});

