test("adam_update: 파라미터 변화 (gradient 방향 감소)", () => {
  const r = runFL8(`
fn make_adam_state(param: i32) -> i32 {
  let state = []
  push(state, t_zeros_like(param))
  push(state, t_zeros_like(param))
  push(state, 0)
  return state
}
fn adam_update(param: i32, grad: i32, state: i32,
               lr: i32, b1: i32, b2: i32, eps: i32) -> i32 {
  let m = state[0]
  let v = state[1]
  let step = state[2] + 1
  state[2] = step
  let m_new = t_add(t_scale(m, b1), t_scale(grad, 1.0 - b1))
  state[0] = m_new
  let v_new = t_add(t_scale(v, b2), t_scale(t_pow2(grad), 1.0 - b2))
  state[1] = v_new
  let bc1 = 1.0 - pow(b1, float(step))
  let bc2 = 1.0 - pow(b2, float(step))
  let m_hat = t_scale(m_new, 1.0 / bc1)
  let v_hat = t_scale(v_new, 1.0 / bc2)
  let denom = t_add(t_sqrt(v_hat), t_scale(t_ones_like(v_hat), eps))
  let delta = t_scale(t_div(m_hat, denom), lr)
  return t_sub(param, delta)
}
let p = reshape(zeros(4), 4)
let g = reshape(ones(4), 4)
let st = make_adam_state(p)
let p2 = adam_update(p, g, st, 0.01, 0.9, 0.999, 0.00000001)
