// FreeLang v8 ML — GPT Inference (Phase M)
//
// 외부에서 JSON으로 파라미터를 받아 텍스트 생성
// 출력: JSON 형식 (Go 서버가 파싱)
//
// 사용: fl8 gpt_inference.fl8 -- <vocab_size> <d> <ffn> <layers> <seq> <ids...>
//
// ── 인라인 의존 함수 ─────────────────────────────────────────

fn embed_seq(table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let out = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(table, int(ids[i]))
    t_set_row(out, i, row)
  }
  return out
}

fn embed_forward(tok_table: i32, pos_table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let tok_e = embed_seq(tok_table, ids, seq_len, d_model)
  let pos_e = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(pos_table, i)
    t_set_row(pos_e, i, row)
  }
  return t_add(tok_e, pos_e)
}

fn linear_fwd(x: i32, W: i32, b: i32, seq_len: i32, out_dim: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(out, i)
    t_set_row(out, i, t_add(row, b))
  }
  return out
}

fn row_softmax(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) {
    let row = t_row(t, i)
    t_set_row(out, i, t_softmax(row))
  }
  return out
}

fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32,
            seq_len: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, seq_len, d)
  let K = linear_fwd(x, Wk, bk, seq_len, d)
  let V = linear_fwd(x, Wv, bv, seq_len, d)
  let Kt = transpose(K)
  let scores = t_scale(matmul(Q, Kt), 1.0 / sqrt(float(d)))
  let sm2 = t_add(scores, t_causal_mask(seq_len))
  return linear_fwd(matmul(row_softmax(sm2, seq_len, seq_len), V), Wo, bo, seq_len, d)
}

fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32,
           seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let h = matmul(x, W1)
  let i = 0
  for i in range(seq_len) {
    t_set_row(h, i, t_add(t_row(h, i), b1))
  }
  let out = matmul(t_gelu(h), W2)
  for i in range(seq_len) {
    t_set_row(out, i, t_add(t_row(out, i), b2))
  }
  return out
}

fn row_layer_norm(x: i32, scale: i32, bias: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_layer_norm(t_row(x, i), scale, bias, 0.00001))
  }
  return out
}

fn block_fwd(x: i32,
             Wq: i32, Wk: i32, Wv: i32, Wo: i32,
             bq: i32, bk: i32, bv: i32, bo: i32,
             W1: i32, b1: i32, W2: i32, b2: i32,
             ln1s: i32, ln1b: i32, ln2s: i32, ln2b: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let x1 = row_layer_norm(x, ln1s, ln1b, seq_len, d)
  let x2 = t_add(x, attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, seq_len, d))
  let x3 = row_layer_norm(x2, ln2s, ln2b, seq_len, d)
  return t_add(x2, ffn_fwd(x3, W1, b1, W2, b2, seq_len, d, ffn_dim))
}

fn layer_fwd(x: i32, params: i32, li: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let base = li * 16
  return block_fwd(x,
    params[base+0], params[base+1], params[base+2], params[base+3],
    params[base+4], params[base+5], params[base+6], params[base+7],
    params[base+8], params[base+9], params[base+10], params[base+11],
    params[base+12], params[base+13], params[base+14], params[base+15],
    seq_len, d, ffn_dim)
}

fn make_layer_params(d: i32, ffn_dim: i32) -> i32 {
  let p = []
  push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, randn(d, ffn_dim))
  push(p, reshape(zeros(ffn_dim), ffn_dim))
  push(p, randn(ffn_dim, d))
  push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  return p
}

fn make_gpt_model(vocab_size: i32, d: i32, ffn_dim: i32,
                  num_layers: i32, max_seq_len: i32) -> i32 {
  let model = []
  push(model, randn(vocab_size, d))
  push(model, randn(max_seq_len, d))
  let all_params = []
  let li = 0
  for li in range(num_layers) {
    let lp = make_layer_params(d, ffn_dim)
    let pi = 0
    for pi in range(16) {
      push(all_params, lp[pi])
    }
  }
  push(model, all_params)
  push(model, reshape(ones(d), d))
  push(model, reshape(zeros(d), d))
  push(model, randn(d, vocab_size))
  push(model, reshape(zeros(vocab_size), vocab_size))
  return model
}

fn model_forward(model: i32, ids: i32,
                 num_layers: i32, seq_len: i32,
                 d: i32, ffn_dim: i32, vocab_size: i32) -> i32 {
  let tok_table     = model[0]
  let pos_table     = model[1]
  let all_params    = model[2]
  let final_ln_scale = model[3]
  let final_ln_bias  = model[4]
  let lm_head       = model[5]
  let lm_bias       = model[6]

  let x = embed_forward(tok_table, pos_table, ids, seq_len, d)
  let li = 0
  for li in range(num_layers) {
    x = layer_fwd(x, all_params, li, seq_len, d, ffn_dim)
  }
  let last_row = t_row(x, seq_len - 1)
  let ln_out   = t_layer_norm(last_row, final_ln_scale, final_ln_bias, 0.00001)
  let ln_2d    = reshape(ln_out, 1, d)
  let logits   = t_row(matmul(ln_2d, lm_head), 0)
  return t_add(logits, lm_bias)
}

// ─── Top-K Temperature Sampling ─────────────────────────────
// top_k_sample(logits, k, temperature) → token_id

fn top_k_sample(logits: i32, k: i32, temperature: i32) -> i32 {
  // 1) temperature 스케일
  let scaled = t_scale(logits, 1.0 / temperature)

  // 2) softmax → 확률
  let probs = t_softmax(scaled)

  // 3) top-k: k개 최고 확률 인덱스 찾기
  let vocab_size = len(shape(probs))
  // shape가 [n] 형태이므로 shape(probs)[0] 대신 t_rows 활용
  // → logits는 1D이므로 data 길이 = vocab_size

  // 가장 높은 확률 인덱스를 단순히 argmax로 (k=1 근사, 추후 개선)
  return t_argmax(probs)
}

// ─── 자동회귀 생성 ───────────────────────────────────────────
// autoregressive_generate(model, seed_ids, max_new, num_layers,
//                         d, ffn, vocab, max_seq, temperature) → ids 배열

fn autoregressive_generate(model: i32, seed_ids: i32,
                            max_new: i32, num_layers: i32,
                            d: i32, ffn: i32, vocab: i32,
                            max_seq: i32, temperature: i32) -> i32 {
  let ids = seed_ids
  let step = 0
  for step in range(max_new) {
    let cur_len = len(ids)
    // seq_len은 max_seq 초과하지 않도록
    let use_len = cur_len
    if cur_len > max_seq {
      use_len = max_seq
    }
    // 마지막 use_len 토큰 슬라이스 (단순화: 배열 끝부터)
    let start = cur_len - use_len
    let window = []
    let wi = start
    for wi in range(cur_len) {
      push(window, ids[wi])
    }

    let logits = model_forward(model, window, num_layers, use_len, d, ffn, vocab)
    let next_tok = top_k_sample(logits, 5, temperature)
    push(ids, next_tok)
  }
  return ids
}

// ─── 메인 실행 ───────────────────────────────────────────────

let vocab_size  = 20
let d           = 8
let ffn_dim     = 16
let num_layers  = 2
let max_seq_len = 8
let temperature = 0.8
let max_new     = 5

let model = make_gpt_model(vocab_size, d, ffn_dim, num_layers, max_seq_len)
let seed_ids = [3, 7, 1]

let generated = autoregressive_generate(model, seed_ids, max_new,
                                         num_layers, d, ffn_dim,
                                         vocab_size, max_seq_len, temperature)

print("generated_ids:", generated)
print("generated_len:", len(generated))

// 단일 forward pass logits 확인
let logits = model_forward(model, seed_ids, num_layers, 3, d, ffn_dim, vocab_size)
print("logits_shape:", shape(logits))
print("top_token:", t_argmax(logits))
print("probs_sum:", t_sum(t_softmax(logits)))
print("PASS: gpt_inference.fl8")

