package main

// FL8Runner: Go에서 FL8 인터프리터(Node.js)를 subprocess로 호출
//
// 동작:
//   1. fl8_script.fl8 임시 파일 생성
//   2. npx ts-node --transpile-only src/fl8.ts <script> 실행
//   3. stdout에서 "KEY: VALUE" 라인 파싱
//   4. 결과 맵 반환

import (
	"bufio"
	"bytes"
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// FL8RunResult: FL8 실행 결과
type FL8RunResult struct {
	Output   map[string]string // "KEY: VALUE" 라인 파싱
	RawOut   string            // 전체 stdout
	Elapsed  time.Duration
	ExitCode int
	Error    string
}

// FL8Runner 설정
type FL8Runner struct {
	ProjectDir string // freelang-v8-ml 경로
	NodeBin    string // node 실행파일 (기본: node)
}

// 기본 Runner 생성
func NewFL8Runner(projectDir string) *FL8Runner {
	return &FL8Runner{
		ProjectDir: projectDir,
		NodeBin:    "node",
	}
}

// RunScript: FL8 스크립트 파일 실행
func (r *FL8Runner) RunScript(scriptPath string) *FL8RunResult {
	start := time.Now()

	// ts-node로 fl8.ts 엔트리포인트를 통해 실행
	fl8EntryPoint := filepath.Join(r.ProjectDir, "src", "fl8.ts")

	cmd := exec.Command(
		"npx", "ts-node", "--transpile-only",
		fl8EntryPoint,
		scriptPath,
	)
	cmd.Dir = r.ProjectDir

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	elapsed := time.Since(start)

	result := &FL8RunResult{
		Output:  parseFL8Output(stdout.String()),
		RawOut:  stdout.String(),
		Elapsed: elapsed,
	}

	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			result.ExitCode = exitErr.ExitCode()
		} else {
			result.ExitCode = -1
		}
		result.Error = stderr.String()
	}

	return result
}

// RunCode: 인라인 FL8 코드 실행 (임시 파일 생성)
func (r *FL8Runner) RunCode(code string) *FL8RunResult {
	start := time.Now()

	fl8EntryPoint := filepath.Join(r.ProjectDir, "src", "fl8.ts")

	// -e 플래그로 인라인 코드 실행
	cmd := exec.Command(
		"npx", "ts-node", "--transpile-only",
		fl8EntryPoint,
		"-e", code,
	)
	cmd.Dir = r.ProjectDir

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	elapsed := time.Since(start)

	result := &FL8RunResult{
		Output:  parseFL8Output(stdout.String()),
		RawOut:  stdout.String(),
		Elapsed: elapsed,
	}

	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			result.ExitCode = exitErr.ExitCode()
		} else {
			result.ExitCode = -1
		}
		result.Error = stderr.String()
	}

	return result
}

// parseFL8Output: "KEY: VALUE" 라인을 맵으로 파싱
// print("key:", value) → "key: VALUE"
func parseFL8Output(raw string) map[string]string {
	result := make(map[string]string)
	scanner := bufio.NewScanner(strings.NewReader(raw))
	for scanner.Scan() {
		line := scanner.Text()
		idx := strings.Index(line, ":")
		if idx > 0 && idx < len(line)-1 {
			key := strings.TrimSpace(line[:idx])
			val := strings.TrimSpace(line[idx+1:])
			// 키에 공백이 있으면 첫 단어만 키로 사용
			keyParts := strings.Fields(key)
			if len(keyParts) == 1 {
				result[key] = val
			}
		}
	}
	return result
}

// GetFL8RuntimeInfo: FL8 런타임 버전/상태 확인
func (r *FL8Runner) GetFL8RuntimeInfo() (string, error) {
	cmd := exec.Command("npx", "ts-node", "--transpile-only",
		filepath.Join(r.ProjectDir, "src", "fl8.ts"),
		"-e", `print("version:", "8.0.0") print("status:", "ok")`,
	)
	cmd.Dir = r.ProjectDir

	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &out

	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("FL8 런타임 확인 실패: %v", err)
	}
	return out.String(), nil
}

