package main

// Phase M: FL8 GPT 추론 서버
//
// 엔드포인트:
//   GET  /api/fl8/status       — FL8 런타임 상태
//   POST /api/fl8/generate     — FL8 GPT로 텍스트 생성
//   POST /api/fl8/forward      — 단일 forward pass (logits 반환)
//   GET  /api/fl8/capabilities — 지원 기능 목록

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

// ── 요청/응답 구조체 ─────────────────────────────────────────

type FL8GenerateRequest struct {
	SeedIds     []int   `json:"seed_ids"`      // 시드 토큰 ID 배열
	MaxNew      int     `json:"max_new"`       // 생성할 새 토큰 수 (기본: 5)
	VocabSize   int     `json:"vocab_size"`    // vocab 크기 (기본: 20)
	D           int     `json:"d"`             // 임베딩 차원 (기본: 8)
	FfnDim      int     `json:"ffn_dim"`       // FFN 차원 (기본: 16)
	NumLayers   int     `json:"num_layers"`    // 레이어 수 (기본: 2)
	MaxSeqLen   int     `json:"max_seq_len"`   // 최대 시퀀스 길이 (기본: 8)
	Temperature float64 `json:"temperature"`   // 샘플링 온도 (기본: 0.8)
}

type FL8GenerateResponse struct {
	SeedIds      []int    `json:"seed_ids"`
	GeneratedIds []int    `json:"generated_ids"`
	NewTokens    []int    `json:"new_tokens"`
	NumNew       int      `json:"num_new"`
	ElapsedMs    int64    `json:"elapsed_ms"`
	ModelConfig  ModelCfg `json:"model_config"`
	Status       string   `json:"status"`
	RawOutput    string   `json:"raw_output,omitempty"`
}

type FL8ForwardRequest struct {
	Ids       []int `json:"ids"`
	VocabSize int   `json:"vocab_size"`
	D         int   `json:"d"`
	FfnDim    int   `json:"ffn_dim"`
	NumLayers int   `json:"num_layers"`
	MaxSeqLen int   `json:"max_seq_len"`
}

type FL8ForwardResponse struct {
	LogitsShape []int   `json:"logits_shape"`
	TopToken    int     `json:"top_token"`
	ProbsSum    float64 `json:"probs_sum"`
	ElapsedMs   int64   `json:"elapsed_ms"`
	Status      string  `json:"status"`
}

type ModelCfg struct {
	VocabSize int     `json:"vocab_size"`
	D         int     `json:"d"`
	FfnDim    int     `json:"ffn_dim"`
	NumLayers int     `json:"num_layers"`
	MaxSeqLen int     `json:"max_seq_len"`
	Temp      float64 `json:"temperature"`
}

type FL8StatusResponse struct {
	Status      string `json:"status"`
	Runtime     string `json:"runtime"`
	Version     string `json:"version"`
	ProjectDir  string `json:"project_dir"`
	NodeVersion string `json:"node_version"`
	Capabilities []string `json:"capabilities"`
	CheckedAt   string `json:"checked_at"`
}

// ── FL8 프로젝트 경로 찾기 ───────────────────────────────────

func findFL8ProjectDir() string {
	// 환경변수 우선
	if d := os.Getenv("FL8_PROJECT_DIR"); d != "" {
		return d
	}
	// 공통 경로 시도
	candidates := []string{
		"/data/data/com.termux/files/home/projects/freelang-v8-ml",
		"../freelang-v8-ml",
		"../../freelang-v8-ml",
	}
	for _, c := range candidates {
		if _, err := os.Stat(filepath.Join(c, "src", "fl8.ts")); err == nil {
			abs, _ := filepath.Abs(c)
			return abs
		}
	}
	return ""
}

// ── /api/fl8/status ─────────────────────────────────────────

func handleFL8Status(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	projectDir := findFL8ProjectDir()
	resp := FL8StatusResponse{
		Status:     "ok",
		Runtime:    "FL8 (FreeLang v8 ML)",
		Version:    "8.0.0",
		ProjectDir: projectDir,
		CheckedAt:  time.Now().Format(time.RFC3339),
		Capabilities: []string{
			"gpt_model_forward",
			"autoregressive_generate",
			"ce_loss",
			"adam_optimizer",
			"transformer_block",
			"causal_attention",
		},
	}

	if projectDir == "" {
		resp.Status = "degraded"
		resp.Runtime = "FL8 project not found"
	} else {
		runner := NewFL8Runner(projectDir)
		_, err := runner.GetFL8RuntimeInfo()
		if err != nil {
			resp.Status = "degraded"
			resp.Runtime = fmt.Sprintf("FL8 error: %v", err)
		}
	}

	json.NewEncoder(w).Encode(resp)
}

// ── /api/fl8/generate ────────────────────────────────────────

func handleFL8Generate(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		http.Error(w, `{"error":"POST 필요"}`, http.StatusMethodNotAllowed)
		return
	}

	// 요청 파싱
	var req FL8GenerateRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, `{"error":"JSON 파싱 실패"}`, http.StatusBadRequest)
		return
	}

	// 기본값 설정
	if len(req.SeedIds) == 0 { req.SeedIds = []int{3, 7, 1} }
	if req.MaxNew == 0       { req.MaxNew = 5 }
	if req.VocabSize == 0    { req.VocabSize = 20 }
	if req.D == 0            { req.D = 8 }
	if req.FfnDim == 0       { req.FfnDim = 16 }
	if req.NumLayers == 0    { req.NumLayers = 2 }
	if req.MaxSeqLen == 0    { req.MaxSeqLen = 8 }
	if req.Temperature == 0  { req.Temperature = 0.8 }

	projectDir := findFL8ProjectDir()
	if projectDir == "" {
		http.Error(w, `{"error":"FL8 프로젝트 디렉토리를 찾을 수 없습니다"}`, http.StatusInternalServerError)
		return
	}

	// FL8 코드 생성 (인라인)
	seedStr := intSliceToFL8Array(req.SeedIds)
	code := buildGenerateCode(seedStr, req)

	runner := NewFL8Runner(projectDir)
	start := time.Now()
	result := runner.RunCode(code)
	elapsed := time.Since(start).Milliseconds()

	if result.ExitCode != 0 {
		resp := map[string]interface{}{
			"error":      "FL8 실행 실패",
			"exit_code":  result.ExitCode,
			"stderr":     result.Error,
			"raw_output": result.RawOut,
		}
		w.WriteHeader(http.StatusInternalServerError)
		json.NewEncoder(w).Encode(resp)
		return
	}

	// 결과 파싱
	generatedIds := parseIntArray(result.Output["generated_ids"])
	newTokens := generatedIds[len(req.SeedIds):]

	resp := FL8GenerateResponse{
		SeedIds:      req.SeedIds,
		GeneratedIds: generatedIds,
		NewTokens:    newTokens,
		NumNew:       len(newTokens),
		ElapsedMs:    elapsed,
		ModelConfig: ModelCfg{
			VocabSize: req.VocabSize,
			D:         req.D,
			FfnDim:    req.FfnDim,
			NumLayers: req.NumLayers,
			MaxSeqLen: req.MaxSeqLen,
			Temp:      req.Temperature,
		},
		Status:    "ok",
		RawOutput: result.RawOut,
	}

	json.NewEncoder(w).Encode(resp)
}

// ── /api/fl8/forward ─────────────────────────────────────────

func handleFL8Forward(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		http.Error(w, `{"error":"POST 필요"}`, http.StatusMethodNotAllowed)
		return
	}

	var req FL8ForwardRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, `{"error":"JSON 파싱 실패"}`, http.StatusBadRequest)
		return
	}
	if len(req.Ids) == 0    { req.Ids = []int{1, 2, 3} }
	if req.VocabSize == 0   { req.VocabSize = 20 }
	if req.D == 0           { req.D = 8 }
	if req.FfnDim == 0      { req.FfnDim = 16 }
	if req.NumLayers == 0   { req.NumLayers = 2 }
	if req.MaxSeqLen == 0   { req.MaxSeqLen = 8 }

	projectDir := findFL8ProjectDir()
	if projectDir == "" {
		http.Error(w, `{"error":"FL8 프로젝트 없음"}`, http.StatusInternalServerError)
		return
	}

	code := buildForwardCode(intSliceToFL8Array(req.Ids), req)
	runner := NewFL8Runner(projectDir)
	start := time.Now()
	result := runner.RunCode(code)
	elapsed := time.Since(start).Milliseconds()

	if result.ExitCode != 0 {
		resp := map[string]interface{}{
			"error":  "FL8 실행 실패",
			"stderr": result.Error,
		}
		w.WriteHeader(http.StatusInternalServerError)
		json.NewEncoder(w).Encode(resp)
		return
	}

	topToken := 0
	if v, ok := result.Output["top_token"]; ok {
		topToken, _ = strconv.Atoi(strings.TrimSpace(v))
	}
	probsSum := 0.0
	if v, ok := result.Output["probs_sum"]; ok {
		probsSum, _ = strconv.ParseFloat(strings.TrimSpace(v), 64)
	}

	resp := FL8ForwardResponse{
		LogitsShape: []int{req.VocabSize},
		TopToken:    topToken,
		ProbsSum:    probsSum,
		ElapsedMs:   elapsed,
		Status:      "ok",
	}
	json.NewEncoder(w).Encode(resp)
}

// ── /api/fl8/capabilities ────────────────────────────────────

func handleFL8Capabilities(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	resp := map[string]interface{}{
		"phase":    "M",
		"language": "FreeLang v8 ML (FL8)",
		"runtime":  "ts-node (TypeScript interpreter)",
		"modules": []map[string]string{
			{"name": "gpt_embedding.fl8",  "desc": "Token + Positional Embedding"},
			{"name": "gpt_attention.fl8",  "desc": "Causal Self-Attention"},
			{"name": "gpt_block.fl8",      "desc": "Pre-LN Transformer Block"},
			{"name": "gpt_model.fl8",      "desc": "Full GPT Forward Pass"},
			{"name": "gpt_loss.fl8",       "desc": "Cross-Entropy Loss"},
			{"name": "gpt_adam.fl8",       "desc": "Adam Optimizer"},
			{"name": "gpt_train_step.fl8", "desc": "Numerical Gradient + Train Step"},
			{"name": "gpt_inference.fl8",  "desc": "Autoregressive Generation"},
		},
		"endpoints": []map[string]string{
			{"method": "GET",  "path": "/api/fl8/status",       "desc": "FL8 런타임 상태"},
			{"method": "POST", "path": "/api/fl8/generate",     "desc": "자동회귀 텍스트 생성"},
			{"method": "POST", "path": "/api/fl8/forward",      "desc": "단일 forward pass"},
			{"method": "GET",  "path": "/api/fl8/capabilities", "desc": "지원 기능 목록"},
		},
		"note": "FL8은 학습/추론을 위한 ML 특화 DSL입니다. import 없음, 순수 함수형.",
	}
	json.NewEncoder(w).Encode(resp)
}

// ── 라우트 등록 ──────────────────────────────────────────────

func RegisterFL8Routes(mux *http.ServeMux) {
	mux.HandleFunc("/api/fl8/status",       handleFL8Status)
	mux.HandleFunc("/api/fl8/generate",     handleFL8Generate)
	mux.HandleFunc("/api/fl8/forward",      handleFL8Forward)
	mux.HandleFunc("/api/fl8/capabilities", handleFL8Capabilities)
}

// ── 헬퍼 ─────────────────────────────────────────────────────

func intSliceToFL8Array(ids []int) string {
	parts := make([]string, len(ids))
	for i, v := range ids {
		parts[i] = strconv.Itoa(v)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func parseIntArray(s string) []int {
	s = strings.Trim(s, "[] ")
	if s == "" { return nil }
	parts := strings.Split(s, ",")
	result := make([]int, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if v, err := strconv.Atoi(p); err == nil {
			result = append(result, v)
		}
	}
	return result
}

func buildGenerateCode(seedStr string, req FL8GenerateRequest) string {
	// gpt_inference.fl8의 인라인 의존 함수 + 생성 코드
	inferenceScript := findFL8ProjectDir() + "/src/gpt/gpt_inference.fl8"
	// 스크립트 파일이 있으면 파라미터만 오버라이드해서 실행
	// 없으면 인라인 코드 생성
	if _, err := os.Stat(inferenceScript); err == nil {
		// 파일이 있으면 파일 경로 사용 불가 (RunCode는 -e 방식)
		// → 핵심 부분만 인라인으로 빠르게 실행
		_ = inferenceScript
	}

	return fmt.Sprintf(`
let vocab_size  = %d
let d           = %d
let ffn_dim     = %d
let num_layers  = %d
let max_seq_len = %d
let temperature = %f
let max_new     = %d

fn embed_seq(table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let out = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(table, int(ids[i]))
    t_set_row(out, i, row)
  }
  return out
}

fn embed_forward(tok_table: i32, pos_table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let tok_e = embed_seq(tok_table, ids, seq_len, d_model)
  let pos_e = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    t_set_row(pos_e, i, t_row(pos_table, i))
  }
  return t_add(tok_e, pos_e)
}

fn linear_fwd(x: i32, W: i32, b: i32, seq_len: i32, out_dim: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_add(t_row(out, i), b))
  }
  return out
}

fn row_softmax(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) {
    t_set_row(out, i, t_softmax(t_row(t, i)))
  }
  return out
}

fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32,
            seq_len: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, seq_len, d)
  let K = linear_fwd(x, Wk, bk, seq_len, d)
  let V = linear_fwd(x, Wv, bv, seq_len, d)
  let scores = t_scale(matmul(Q, transpose(K)), 1.0 / sqrt(float(d)))
  let sm2 = t_add(scores, t_causal_mask(seq_len))
  return linear_fwd(matmul(row_softmax(sm2, seq_len, seq_len), V), Wo, bo, seq_len, d)
}

fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32,
           seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let h = matmul(x, W1)
  let i = 0
  for i in range(seq_len) {
    t_set_row(h, i, t_add(t_row(h, i), b1))
  }
  let out = matmul(t_gelu(h), W2)
  for i in range(seq_len) {
    t_set_row(out, i, t_add(t_row(out, i), b2))
  }
  return out
}

fn row_layer_norm(x: i32, scale: i32, bias: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_layer_norm(t_row(x, i), scale, bias, 0.00001))
  }
  return out
}

fn block_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
             bq: i32, bk: i32, bv: i32, bo: i32,
             W1: i32, b1: i32, W2: i32, b2: i32,
             ln1s: i32, ln1b: i32, ln2s: i32, ln2b: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let x1 = row_layer_norm(x, ln1s, ln1b, seq_len, d)
  let x2 = t_add(x, attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, seq_len, d))
  return t_add(x2, ffn_fwd(row_layer_norm(x2, ln2s, ln2b, seq_len, d), W1, b1, W2, b2, seq_len, d, ffn_dim))
}

fn layer_fwd(x: i32, params: i32, li: i32, seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let base = li * 16
  return block_fwd(x,
    params[base+0], params[base+1], params[base+2], params[base+3],
    params[base+4], params[base+5], params[base+6], params[base+7],
    params[base+8], params[base+9], params[base+10], params[base+11],
    params[base+12], params[base+13], params[base+14], params[base+15],
    seq_len, d, ffn_dim)
}

fn make_layer_params(d: i32, ffn_dim: i32) -> i32 {
  let p = []
  push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, randn(d, ffn_dim))
  push(p, reshape(zeros(ffn_dim), ffn_dim))
  push(p, randn(ffn_dim, d))
  push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  return p
}

fn make_gpt_model(vocab_size: i32, d: i32, ffn_dim: i32, num_layers: i32, max_seq_len: i32) -> i32 {
  let model = []
  push(model, randn(vocab_size, d))
  push(model, randn(max_seq_len, d))
  let all_params = []
  let li = 0
  for li in range(num_layers) {
    let lp = make_layer_params(d, ffn_dim)
    let pi = 0
    for pi in range(16) { push(all_params, lp[pi]) }
  }
  push(model, all_params)
  push(model, reshape(ones(d), d))
  push(model, reshape(zeros(d), d))
  push(model, randn(d, vocab_size))
  push(model, reshape(zeros(vocab_size), vocab_size))
  return model
}

fn model_forward(model: i32, ids: i32, num_layers: i32, seq_len: i32,
                 d: i32, ffn_dim: i32, vocab_size: i32) -> i32 {
  let x = embed_forward(model[0], model[1], ids, seq_len, d)
  let li = 0
  for li in range(num_layers) {
    x = layer_fwd(x, model[2], li, seq_len, d, ffn_dim)
  }
  let ln_out = t_layer_norm(t_row(x, seq_len - 1), model[3], model[4], 0.00001)
  let logits  = t_row(matmul(reshape(ln_out, 1, d), model[5]), 0)
  return t_add(logits, model[6])
}

let model    = make_gpt_model(vocab_size, d, ffn_dim, num_layers, max_seq_len)
let ids      = %s
let step     = 0
for step in range(max_new) {
