// ── 헬퍼 ─────────────────────────────────────────────────────

func intSliceToFL8Array(ids []int) string {
	parts := make([]string, len(ids))
	for i, v := range ids {
		parts[i] = strconv.Itoa(v)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func parseIntArray(s string) []int {
	s = strings.Trim(s, "[] ")
	if s == "" { return nil }
	parts := strings.Split(s, ",")
	result := make([]int, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if v, err := strconv.Atoi(p); err == nil {
			result = append(result, v)
		}
	}
	return result
}

func buildGenerateCode(seedStr string, req FL8GenerateRequest) string {
	// gpt_inference.fl8의 인라인 의존 함수 + 생성 코드
	inferenceScript := findFL8ProjectDir() + "/src/gpt/gpt_inference.fl8"
	// 스크립트 파일이 있으면 파라미터만 오버라이드해서 실행
	// 없으면 인라인 코드 생성
	if _, err := os.Stat(inferenceScript); err == nil {
		// 파일이 있으면 파일 경로 사용 불가 (RunCode는 -e 방식)
		// → 핵심 부분만 인라인으로 빠르게 실행
		_ = inferenceScript
	}

	return fmt.Sprintf(`
let vocab_size  = %d
let d           = %d
let ffn_dim     = %d
let num_layers  = %d
let max_seq_len = %d
let temperature = %f
let max_new     = %d

fn embed_seq(table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let out = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(table, int(ids[i]))
    t_set_row(out, i, row)
  }
  return out
}

fn embed_forward(tok_table: i32, pos_table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let tok_e = embed_seq(tok_table, ids, seq_len, d_model)
  let pos_e = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    t_set_row(pos_e, i, t_row(pos_table, i))
  }
  return t_add(tok_e, pos_e)
}

fn linear_fwd(x: i32, W: i32, b: i32, seq_len: i32, out_dim: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_add(t_row(out, i), b))
  }
  return out
}

fn row_softmax(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) {
    t_set_row(out, i, t_softmax(t_row(t, i)))
  }
  return out
}

fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32,
            seq_len: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, seq_len, d)
  let K = linear_fwd(x, Wk, bk, seq_len, d)
  let V = linear_fwd(x, Wv, bv, seq_len, d)
  let scores = t_scale(matmul(Q, transpose(K)), 1.0 / sqrt(float(d)))
  let sm2 = t_add(scores, t_causal_mask(seq_len))
  return linear_fwd(matmul(row_softmax(sm2, seq_len, seq_len), V), Wo, bo, seq_len, d)
}

fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32,
           seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let h = matmul(x, W1)
  let i = 0
  for i in range(seq_len) {
    t_set_row(h, i, t_add(t_row(h, i), b1))
  }
  let out = matmul(t_gelu(h), W2)
  for i in range(seq_len) {
    t_set_row(out, i, t_add(t_row(out, i), b2))
  }
  return out
}

fn row_layer_norm(x: i32, scale: i32, bias: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_layer_norm(t_row(x, i), scale, bias, 0.00001))
  }
  return out
}

fn block_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
             bq: i32, bk: i32, bv: i32, bo: i32,
             W1: i32, b1: i32, W2: i32, b2: i32,
             ln1s: i32, ln1b: i32, ln2s: i32, ln2b: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let x1 = row_layer_norm(x, ln1s, ln1b, seq_len, d)
  let x2 = t_add(x, attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, seq_len, d))
  return t_add(x2, ffn_fwd(row_layer_norm(x2, ln2s, ln2b, seq_len, d), W1, b1, W2, b2, seq_len, d, ffn_dim))
}

fn layer_fwd(x: i32, params: i32, li: i32, seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let base = li * 16
  return block_fwd(x,
    params[base+0], params[base+1], params[base+2], params[base+3],
    params[base+4], params[base+5], params[base+6], params[base+7],
    params[base+8], params[base+9], params[base+10], params[base+11],
    params[base+12], params[base+13], params[base+14], params[base+15],
    seq_len, d, ffn_dim)
}

fn make_layer_params(d: i32, ffn_dim: i32) -> i32 {
  let p = []
  push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, randn(d, ffn_dim))
  push(p, reshape(zeros(ffn_dim), ffn_dim))
  push(p, randn(ffn_dim, d))
  push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  return p
}

fn make_gpt_model(vocab_size: i32, d: i32, ffn_dim: i32, num_layers: i32, max_seq_len: i32) -> i32 {
  let model = []
  push(model, randn(vocab_size, d))
  push(model, randn(max_seq_len, d))
  let all_params = []
  let li = 0
  for li in range(num_layers) {
    let lp = make_layer_params(d, ffn_dim)
    let pi = 0
    for pi in range(16) { push(all_params, lp[pi]) }
  }
  push(model, all_params)
  push(model, reshape(ones(d), d))
  push(model, reshape(zeros(d), d))
  push(model, randn(d, vocab_size))
  push(model, reshape(zeros(vocab_size), vocab_size))
  return model
}

fn model_forward(model: i32, ids: i32, num_layers: i32, seq_len: i32,
                 d: i32, ffn_dim: i32, vocab_size: i32) -> i32 {
  let x = embed_forward(model[0], model[1], ids, seq_len, d)
  let li = 0
  for li in range(num_layers) {
    x = layer_fwd(x, model[2], li, seq_len, d, ffn_dim)
  }
  let ln_out = t_layer_norm(t_row(x, seq_len - 1), model[3], model[4], 0.00001)
  let logits  = t_row(matmul(reshape(ln_out, 1, d), model[5]), 0)
  return t_add(logits, model[6])
}

let model    = make_gpt_model(vocab_size, d, ffn_dim, num_layers, max_seq_len)
let ids      = %s
let step     = 0
for step in range(max_new) {
  let cur_len = len(ids)
  let logits  = model_forward(model, ids, num_layers, cur_len, d, ffn_dim, vocab_size)
  let probs   = t_softmax(t_scale(logits, 1.0 / temperature))
  let next    = t_argmax(probs)
  push(ids, next)
}
print("generated_ids:", ids)
print("generated_len:", len(ids))
`, req.VocabSize, req.D, req.FfnDim, req.NumLayers, req.MaxSeqLen,
		req.Temperature, req.MaxNew, seedStr)
}

