package main

// Phase M: FL8 GPT 추론 서버
//
// 엔드포인트:
//   GET  /api/fl8/status       — FL8 런타임 상태
//   POST /api/fl8/generate     — FL8 GPT로 텍스트 생성
//   POST /api/fl8/forward      — 단일 forward pass (logits 반환)
//   GET  /api/fl8/capabilities — 지원 기능 목록

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

// ── 요청/응답 구조체 ─────────────────────────────────────────

type FL8GenerateRequest struct {
	SeedIds     []int   `json:"seed_ids"`      // 시드 토큰 ID 배열
	MaxNew      int     `json:"max_new"`       // 생성할 새 토큰 수 (기본: 5)
	VocabSize   int     `json:"vocab_size"`    // vocab 크기 (기본: 20)
	D           int     `json:"d"`             // 임베딩 차원 (기본: 8)
	FfnDim      int     `json:"ffn_dim"`       // FFN 차원 (기본: 16)
	NumLayers   int     `json:"num_layers"`    // 레이어 수 (기본: 2)
	MaxSeqLen   int     `json:"max_seq_len"`   // 최대 시퀀스 길이 (기본: 8)
	Temperature float64 `json:"temperature"`   // 샘플링 온도 (기본: 0.8)
}

type FL8GenerateResponse struct {
	SeedIds      []int    `json:"seed_ids"`
	GeneratedIds []int    `json:"generated_ids"`
	NewTokens    []int    `json:"new_tokens"`
	NumNew       int      `json:"num_new"`
	ElapsedMs    int64    `json:"elapsed_ms"`
	ModelConfig  ModelCfg `json:"model_config"`
	Status       string   `json:"status"`
	RawOutput    string   `json:"raw_output,omitempty"`
}

type FL8ForwardRequest struct {
	Ids       []int `json:"ids"`
	VocabSize int   `json:"vocab_size"`
	D         int   `json:"d"`
	FfnDim    int   `json:"ffn_dim"`
	NumLayers int   `json:"num_layers"`
	MaxSeqLen int   `json:"max_seq_len"`
}

type FL8ForwardResponse struct {
	LogitsShape []int   `json:"logits_shape"`
	TopToken    int     `json:"top_token"`
	ProbsSum    float64 `json:"probs_sum"`
	ElapsedMs   int64   `json:"elapsed_ms"`
	Status      string  `json:"status"`
}

type ModelCfg struct {
	VocabSize int     `json:"vocab_size"`
	D         int     `json:"d"`
	FfnDim    int     `json:"ffn_dim"`
	NumLayers int     `json:"num_layers"`
	MaxSeqLen int     `json:"max_seq_len"`
	Temp      float64 `json:"temperature"`
}

type FL8StatusResponse struct {
	Status      string `json:"status"`
	Runtime     string `json:"runtime"`
	Version     string `json:"version"`
	ProjectDir  string `json:"project_dir"`
	NodeVersion string `json:"node_version"`
	Capabilities []string `json:"capabilities"`
	CheckedAt   string `json:"checked_at"`
}

// ── FL8 프로젝트 경로 찾기 ───────────────────────────────────

func findFL8ProjectDir() string {
	// 환경변수 우선
	if d := os.Getenv("FL8_PROJECT_DIR"); d != "" {
		return d
	}
	// 공통 경로 시도
	candidates := []string{
		"/data/data/com.termux/files/home/projects/freelang-v8-ml",
		"../freelang-v8-ml",
		"../../freelang-v8-ml",
	}
	for _, c := range candidates {
		if _, err := os.Stat(filepath.Join(c, "src", "fl8.ts")); err == nil {
			abs, _ := filepath.Abs(c)
			return abs
		}
	}
	return ""
}

// ── /api/fl8/status ─────────────────────────────────────────

func handleFL8Status(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	projectDir := findFL8ProjectDir()
	resp := FL8StatusResponse{
		Status:     "ok",
		Runtime:    "FL8 (FreeLang v8 ML)",
		Version:    "8.0.0",
		ProjectDir: projectDir,
		CheckedAt:  time.Now().Format(time.RFC3339),
		Capabilities: []string{
			"gpt_model_forward",
			"autoregressive_generate",
			"ce_loss",
			"adam_optimizer",
			"transformer_block",
			"causal_attention",
		},
	}

	if projectDir == "" {
		resp.Status = "degraded"
		resp.Runtime = "FL8 project not found"
	} else {
		runner := NewFL8Runner(projectDir)
		_, err := runner.GetFL8RuntimeInfo()
		if err != nil {
			resp.Status = "degraded"
			resp.Runtime = fmt.Sprintf("FL8 error: %v", err)
		}
	}

	json.NewEncoder(w).Encode(resp)
}

// ── /api/fl8/generate ────────────────────────────────────────

func handleFL8Generate(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		http.Error(w, `{"error":"POST 필요"}`, http.StatusMethodNotAllowed)
		return
	}

	// 요청 파싱
	var req FL8GenerateRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, `{"error":"JSON 파싱 실패"}`, http.StatusBadRequest)
		return
	}

	// 기본값 설정
	if len(req.SeedIds) == 0 { req.SeedIds = []int{3, 7, 1} }
	if req.MaxNew == 0       { req.MaxNew = 5 }
	if req.VocabSize == 0    { req.VocabSize = 20 }
	if req.D == 0            { req.D = 8 }
	if req.FfnDim == 0       { req.FfnDim = 16 }
	if req.NumLayers == 0    { req.NumLayers = 2 }
	if req.MaxSeqLen == 0    { req.MaxSeqLen = 8 }
	if req.Temperature == 0  { req.Temperature = 0.8 }

	projectDir := findFL8ProjectDir()
	if projectDir == "" {
		http.Error(w, `{"error":"FL8 프로젝트 디렉토리를 찾을 수 없습니다"}`, http.StatusInternalServerError)
		return
	}

	// FL8 코드 생성 (인라인)
	seedStr := intSliceToFL8Array(req.SeedIds)
	code := buildGenerateCode(seedStr, req)

	runner := NewFL8Runner(projectDir)
	start := time.Now()
	result := runner.RunCode(code)
	elapsed := time.Since(start).Milliseconds()

	if result.ExitCode != 0 {
		resp := map[string]interface{}{
			"error":      "FL8 실행 실패",
			"exit_code":  result.ExitCode,
			"stderr":     result.Error,
			"raw_output": result.RawOut,
		}
		w.WriteHeader(http.StatusInternalServerError)
		json.NewEncoder(w).Encode(resp)
		return
	}

	// 결과 파싱
	generatedIds := parseIntArray(result.Output["generated_ids"])
	newTokens := generatedIds[len(req.SeedIds):]

	resp := FL8GenerateResponse{
		SeedIds:      req.SeedIds,
		GeneratedIds: generatedIds,
		NewTokens:    newTokens,
		NumNew:       len(newTokens),
		ElapsedMs:    elapsed,
		ModelConfig: ModelCfg{
			VocabSize: req.VocabSize,
			D:         req.D,
			FfnDim:    req.FfnDim,
			NumLayers: req.NumLayers,
			MaxSeqLen: req.MaxSeqLen,
			Temp:      req.Temperature,
		},
		Status:    "ok",
		RawOutput: result.RawOut,
	}

	json.NewEncoder(w).Encode(resp)
}

// ── /api/fl8/forward ─────────────────────────────────────────

func handleFL8Forward(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		http.Error(w, `{"error":"POST 필요"}`, http.StatusMethodNotAllowed)
		return
	}

	var req FL8ForwardRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, `{"error":"JSON 파싱 실패"}`, http.StatusBadRequest)
		return
	}
	if len(req.Ids) == 0    { req.Ids = []int{1, 2, 3} }
	if req.VocabSize == 0   { req.VocabSize = 20 }
	if req.D == 0           { req.D = 8 }
	if req.FfnDim == 0      { req.FfnDim = 16 }
	if req.NumLayers == 0   { req.NumLayers = 2 }
	if req.MaxSeqLen == 0   { req.MaxSeqLen = 8 }

	projectDir := findFL8ProjectDir()
	if projectDir == "" {
		http.Error(w, `{"error":"FL8 프로젝트 없음"}`, http.StatusInternalServerError)
		return
	}

	code := buildForwardCode(intSliceToFL8Array(req.Ids), req)
	runner := NewFL8Runner(projectDir)
	start := time.Now()
	result := runner.RunCode(code)
	elapsed := time.Since(start).Milliseconds()

	if result.ExitCode != 0 {
		resp := map[string]interface{}{
			"error":  "FL8 실행 실패",
			"stderr": result.Error,
		}
		w.WriteHeader(http.StatusInternalServerError)
		json.NewEncoder(w).Encode(resp)
		return
	}

	topToken := 0
	if v, ok := result.Output["top_token"]; ok {
		topToken, _ = strconv.Atoi(strings.TrimSpace(v))
	}
	probsSum := 0.0
	if v, ok := result.Output["probs_sum"]; ok {
		probsSum, _ = strconv.ParseFloat(strings.TrimSpace(v), 64)
	}

	resp := FL8ForwardResponse{
		LogitsShape: []int{req.VocabSize},
		TopToken:    topToken,
		ProbsSum:    probsSum,
		ElapsedMs:   elapsed,
		Status:      "ok",
	}
	json.NewEncoder(w).Encode(resp)
}

// ── /api/fl8/capabilities ────────────────────────────────────

func handleFL8Capabilities(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	resp := map[string]interface{}{
		"phase":    "M",
		"language": "FreeLang v8 ML (FL8)",
		"runtime":  "ts-node (TypeScript interpreter)",
		"modules": []map[string]string{
			{"name": "gpt_embedding.fl8",  "desc": "Token + Positional Embedding"},
			{"name": "gpt_attention.fl8",  "desc": "Causal Self-Attention"},
			{"name": "gpt_block.fl8",      "desc": "Pre-LN Transformer Block"},
			{"name": "gpt_model.fl8",      "desc": "Full GPT Forward Pass"},
			{"name": "gpt_loss.fl8",       "desc": "Cross-Entropy Loss"},
			{"name": "gpt_adam.fl8",       "desc": "Adam Optimizer"},
			{"name": "gpt_train_step.fl8", "desc": "Numerical Gradient + Train Step"},
			{"name": "gpt_inference.fl8",  "desc": "Autoregressive Generation"},
		},
		"endpoints": []map[string]string{
