  return out
}
fn row_softmax(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) {
    t_set_row(out, i, t_softmax(t_row(t, i)))
  }
  return out
}
fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32, seq_len: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, seq_len, d)
  let K = linear_fwd(x, Wk, bk, seq_len, d)
  let V = linear_fwd(x, Wv, bv, seq_len, d)
  let sm2 = t_add(t_scale(matmul(Q, transpose(K)), 1.0 / sqrt(float(d))), t_causal_mask(seq_len))
  return linear_fwd(matmul(row_softmax(sm2, seq_len, seq_len), V), Wo, bo, seq_len, d)
}
fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32, seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let h = matmul(x, W1)
  let i = 0
  for i in range(seq_len) {
    t_set_row(h, i, t_add(t_row(h, i), b1))
  }
  let out = matmul(t_gelu(h), W2)
  for i in range(seq_len) {
    t_set_row(out, i, t_add(t_row(out, i), b2))
  }
  return out
}
fn row_layer_norm(x: i32, scale: i32, bias: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_layer_norm(t_row(x, i), scale, bias, 0.00001))
  }
  return out
}
fn block_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
             bq: i32, bk: i32, bv: i32, bo: i32,
             W1: i32, b1: i32, W2: i32, b2: i32,
             ln1s: i32, ln1b: i32, ln2s: i32, ln2b: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let x1 = row_layer_norm(x, ln1s, ln1b, seq_len, d)
  let x2 = t_add(x, attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, seq_len, d))
  return t_add(x2, ffn_fwd(row_layer_norm(x2, ln2s, ln2b, seq_len, d), W1, b1, W2, b2, seq_len, d, ffn_dim))
}
fn layer_fwd(x: i32, params: i32, li: i32, seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let base = li * 16
  return block_fwd(x,
    params[base+0], params[base+1], params[base+2], params[base+3],
    params[base+4], params[base+5], params[base+6], params[base+7],
    params[base+8], params[base+9], params[base+10], params[base+11],
    params[base+12], params[base+13], params[base+14], params[base+15],
    seq_len, d, ffn_dim)
}
fn make_layer_params(d: i32, ffn_dim: i32) -> i32 {
  let p = []
  push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, randn(d, ffn_dim))
  push(p, reshape(zeros(ffn_dim), ffn_dim))
  push(p, randn(ffn_dim, d))
  push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  return p
}
fn make_gpt_model(vocab_size: i32, d: i32, ffn_dim: i32, num_layers: i32, max_seq_len: i32) -> i32 {
  let model = []
  push(model, randn(vocab_size, d))
  push(model, randn(max_seq_len, d))
  let all_params = []
  let li = 0
  for li in range(num_layers) {
    let lp = make_layer_params(d, ffn_dim)
    let pi = 0
    for pi in range(16) { push(all_params, lp[pi]) }
  }
  push(model, all_params)
  push(model, reshape(ones(d), d))
  push(model, reshape(zeros(d), d))
  push(model, randn(d, vocab_size))
  push(model, reshape(zeros(vocab_size), vocab_size))
  return model
}
let model = make_gpt_model(%d, %d, %d, %d, %d)
let ids   = %s
let seq_len = len(ids)
let logits  = let lx = embed_forward(model[0], model[1], ids, seq_len, %d)
let li = 0
for li in range(%d) {
  lx = layer_fwd(lx, model[2], li, seq_len, %d, %d)
}
let ln_out = t_layer_norm(t_row(lx, seq_len - 1), model[3], model[4], 0.00001)
let logits_row = t_row(matmul(reshape(ln_out, 1, %d), model[5]), 0)
let logits = t_add(logits_row, model[6])
print("top_token:", t_argmax(logits))
print("probs_sum:", t_sum(t_softmax(logits)))
`,
		req.VocabSize, req.D, req.FfnDim, req.NumLayers, req.MaxSeqLen,
		idsStr,
		req.D, req.NumLayers, req.D, req.FfnDim, req.D,
	)
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
)

// ==================================================
// Phase G: REST API 서버
// ==================================================

// API 요청/응답 구조
type GenerateRequest struct {
	Prompt      string  `json:"prompt"`
	MaxTokens   int     `json:"max_tokens"`
	Temperature float64 `json:"temperature"`
	Model       string  `json:"model"` // "simple" or "advanced"
}

type GenerateResponse struct {
	Prompt     string `json:"prompt"`
	Generated  string `json:"generated"`
	FullText   string `json:"full_text"`
	Model      string `json:"model"`
	Tokens     int    `json:"tokens"`
	Time       string `json:"time_ms"`
}

type HealthResponse struct {
	Status  string `json:"status"`
	Model   string `json:"model"`
	Vocab   int    `json:"vocab_size"`
	Ready   bool   `json:"ready"`
}

type ModelInfo struct {
	Name       string `json:"name"`
	VocabSize  int    `json:"vocab_size"`
	EmbedDim   int    `json:"embed_dim"`
	MaxLayers  int    `json:"max_layers"`
	Parameters int    `json:"parameters"`
}

// ==================================================
// 전역 상태
// ==================================================

var (
	charToID map[string]int
	idToChar map[string]string
	models   map[string]*ModelInfo
)

// ==================================================
// HTTP 핸들러
// ==================================================

// 건강 상태 확인
func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	response := HealthResponse{
		Status:  "ok",
		Model:   "FreeLang GPT",
		Vocab:   len(charToID),
		Ready:   true,
	}

	json.NewEncoder(w).Encode(response)
}

// 모델 정보
func handleModelInfo(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	modelList := []ModelInfo{
		{
			Name:       "Simple Linear",
			VocabSize:  11267,
			EmbedDim:   128,
			MaxLayers:  1,
			Parameters: 1400000,
		},
		{
			Name:       "Advanced Multi-Layer",
			VocabSize:  11267,
			EmbedDim:   128,
			MaxLayers:  4,
			Parameters: 2500000,
		},
	}

	w.Header().Set("X-Models-Count", fmt.Sprintf("%d", len(modelList)))
	json.NewEncoder(w).Encode(map[string]interface{}{
		"models": modelList,
		"default": "Simple Linear",
	})
}

// 텍스트 생성 (Main handler)
func handleGenerate(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	// CORS 헤더
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Methods", "POST, OPTIONS")
	w.Header().Set("Access-Control-Allow-Headers", "Content-Type")

	// OPTIONS 요청 처리
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusOK)
		return
	}

	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		json.NewEncoder(w).Encode(map[string]string{
			"error": "Only POST method allowed",
		})
		return
	}

	// 요청 파싱
	var req GenerateRequest
	body, err := io.ReadAll(r.Body)
	if err != nil {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Failed to read body"})
		return
	}
	defer r.Body.Close()

	if err := json.Unmarshal(body, &req); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Invalid JSON"})
		return
	}

	// 검증
	if req.Prompt == "" {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Prompt is required"})
		return
	}

	if req.MaxTokens == 0 {
		req.MaxTokens = 50 // 기본값
	}

	if req.Temperature == 0 {
		req.Temperature = 0.7 // 기본값
	}

	if req.Model == "" {
		req.Model = "simple" // 기본 모델
	}

	// 텍스트 생성 로직 (간단한 버전)
	generated := generateText(req.Prompt, req.MaxTokens, req.Temperature, req.Model)

	// 응답
	response := GenerateResponse{
		Prompt:    req.Prompt,
		Generated: generated,
		FullText:  req.Prompt + generated,
		Model:     req.Model,
		Tokens:    len(strings.Fields(generated)),
		Time:      "0ms",
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(response)
}

// 토크나이저 (Encode)
func handleEncode(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		Text string `json:"text"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Invalid JSON"})
		return
	}

	// 인코딩 (간단한 버전)
	var ids []int
	for _, ch := range req.Text {
		key := fmt.Sprintf("%d", ch)
		if id, ok := charToID[key]; ok {
			ids = append(ids, id)
		}
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]interface{}{
		"text":   req.Text,
		"tokens": ids,
		"count":  len(ids),
	})
}

// 토크나이저 (Decode)
func handleDecode(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		Tokens []int `json:"tokens"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Invalid JSON"})
		return
	}

	// 디코딩 (간단한 버전)
	var text string
	for _, id := range req.Tokens {
		key := fmt.Sprintf("%d", id)
		if ch, ok := idToChar[key]; ok {
			text += ch
		}
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]interface{}{
		"tokens": req.Tokens,
		"text":   text,
	})
}

// 통계
func handleStats(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	stats := map[string]interface{}{
		"vocab_size": len(charToID),
		"models": []map[string]interface{}{
			{
				"name":       "simple",
				"parameters": 1400000,
				"layers":     1,
			},
			{
				"name":       "advanced",
				"parameters": 2500000,
				"layers":     4,
			},
		},
		"data": map[string]interface{}{
			"corpus_size":  "14.5MB",
			"tokens":       "9.8M",
			"sequences":    "8.8M",
			"train_split":  "90%",
			"val_split":    "10%",
		},
	}

	json.NewEncoder(w).Encode(stats)
}

// ==================================================
// 텍스트 생성 (더미 구현)
