// 설정:
//   vocab=8, d=4, ffn=8, layers=1, seq=3
//   데이터: 순차 패턴 [1,2,3]→4, [2,3,4]→5, [3,4,5]→6, [4,5,6]→7
//   업데이트 대상: lm_bias (1D, 수치 미분이 빠름)
//   방법: 수치 미분 + Adam, 15 epoch
//
// ── 인라인 의존 함수 ─────────────────────────────────────────

fn embed_seq(table: i32, ids: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    t_set_row(out, i, t_row(table, int(ids[i])))
  }
  return out
}

fn embed_fwd(tt: i32, pt: i32, ids: i32, sl: i32, d: i32) -> i32 {
  let te = embed_seq(tt, ids, sl, d)
  let pe = zeros(sl, d)
  let i = 0
  for i in range(sl) { t_set_row(pe, i, t_row(pt, i)) }
  return t_add(te, pe)
}

fn linear_fwd(x: i32, W: i32, b: i32, sl: i32, od: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(sl) { t_set_row(out, i, t_add(t_row(out, i), b)) }
  return out
}

fn row_sm(t: i32, rows: i32, cols: i32) -> i32 {
  let out = zeros(rows, cols)
  let i = 0
  for i in range(rows) { t_set_row(out, i, t_softmax(t_row(t, i))) }
  return out
}

fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32, sl: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, sl, d)
  let K = linear_fwd(x, Wk, bk, sl, d)
  let V = linear_fwd(x, Wv, bv, sl, d)
  let sm2 = t_add(t_scale(matmul(Q, transpose(K)), 1.0/sqrt(float(d))),
                  t_causal_mask(sl))
  return linear_fwd(matmul(row_sm(sm2, sl, sl), V), Wo, bo, sl, d)
}

fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32, sl: i32, d: i32, fd: i32) -> i32 {
  let h = matmul(x, W1)
  let i = 0
  for i in range(sl) { t_set_row(h, i, t_add(t_row(h, i), b1)) }
  let out = matmul(t_gelu(h), W2)
  for i in range(sl) { t_set_row(out, i, t_add(t_row(out, i), b2)) }
  return out
}

fn row_ln(x: i32, sc: i32, bi: i32, sl: i32, d: i32) -> i32 {
  let out = zeros(sl, d)
  let i = 0
  for i in range(sl) { t_set_row(out, i, t_layer_norm(t_row(x, i), sc, bi, 0.00001)) }
  return out
}

fn block_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
             bq: i32, bk: i32, bv: i32, bo: i32,
             W1: i32, b1: i32, W2: i32, b2: i32,
             ln1s: i32, ln1b: i32, ln2s: i32, ln2b: i32,
             sl: i32, d: i32, fd: i32) -> i32 {
  let x1 = row_ln(x, ln1s, ln1b, sl, d)
  let x2 = t_add(x, attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, sl, d))
  return t_add(x2, ffn_fwd(row_ln(x2, ln2s, ln2b, sl, d), W1, b1, W2, b2, sl, d, fd))
}

fn layer_fwd(x: i32, p: i32, li: i32, sl: i32, d: i32, fd: i32) -> i32 {
  let base = li * 16
  return block_fwd(x,
    p[base+0], p[base+1], p[base+2], p[base+3],
    p[base+4], p[base+5], p[base+6], p[base+7],
    p[base+8], p[base+9], p[base+10], p[base+11],
    p[base+12], p[base+13], p[base+14], p[base+15],
    sl, d, fd)
}

fn make_lp(d: i32, fd: i32) -> i32 {
  let p = []
  push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, randn(d, fd))
  push(p, reshape(zeros(fd), fd))
  push(p, randn(fd, d))
  push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d)) push(p, reshape(zeros(d), d))
  return p
}

// ─── mini forward (고정 파라미터, lm_bias 교체 가능) ─────────
fn mini_fwd(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32,
            lmh: i32, lmb: i32, ids: i32,
            sl: i32, d: i32, fd: i32, vocab: i32) -> i32 {
  let x = embed_fwd(tt, pt, ids, sl, d)
  let li = 0
  for li in range(1) { x = layer_fwd(x, ap, li, sl, d, fd) }
  let ln_out = t_layer_norm(t_row(x, sl - 1), fls, flb, 0.00001)
  let logits  = t_row(matmul(reshape(ln_out, 1, d), lmh), 0)
  return t_add(logits, lmb)
}

// ─── batch loss (모든 샘플 평균) ────────────────────────────
// data_x: [[1,2,3],[2,3,4],...] → 1D flat [1,2,3,2,3,4,...] seq 배열 목록
// data_y: [4, 5, ...] target 목록

fn batch_loss(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32,
              lmh: i32, lmb: i32,
              data_x: i32, data_y: i32, n_samples: i32,
              sl: i32, d: i32, fd: i32, vocab: i32) -> i32 {
  let total = 0.0
  let i = 0
  for i in range(n_samples) {
    let ids = data_x[i]
    let target = int(data_y[i])
    let logits = mini_fwd(tt, pt, ap, fls, flb, lmh, lmb, ids, sl, d, fd, vocab)
    total = total + t_ce_loss(logits, target)
  }
  return total / float(n_samples)
}

// ─── lm_bias 수치 미분 ───────────────────────────────────────
fn grad_lmb(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32,
            lmh: i32, lmb: i32,
            data_x: i32, data_y: i32, n_samples: i32,
            sl: i32, d: i32, fd: i32, vocab: i32, eps: i32) -> i32 {
  let grad = t_zeros_like(lmb)
  let k = 0
  for k in range(vocab) {
    let lmb_p = t_copy(lmb)
    t_set(lmb_p, k, t_get(lmb_p, k) + eps)
    let loss_p = batch_loss(tt, pt, ap, fls, flb, lmh, lmb_p,
                             data_x, data_y, n_samples, sl, d, fd, vocab)

    let lmb_m = t_copy(lmb)
    t_set(lmb_m, k, t_get(lmb_m, k) - eps)
    let loss_m = batch_loss(tt, pt, ap, fls, flb, lmh, lmb_m,
                             data_x, data_y, n_samples, sl, d, fd, vocab)

    t_set(grad, k, (loss_p - loss_m) / (2.0 * eps))
  }
  return grad
}

// ─── Adam 업데이트 ───────────────────────────────────────────
fn adam_upd(param: i32, g: i32, m: i32, v: i32, step: i32,
            lr: i32, b1: i32, b2: i32, eps: i32) -> i32 {
  let m_new = t_add(t_scale(m, b1), t_scale(g, 1.0 - b1))
  let v_new = t_add(t_scale(v, b2), t_scale(t_pow2(g), 1.0 - b2))
  let bc1   = 1.0 - pow(b1, float(step))
  let bc2   = 1.0 - pow(b2, float(step))
  let m_hat = t_scale(m_new, 1.0 / bc1)
  let v_hat = t_scale(v_new, 1.0 / bc2)
  let denom = t_add(t_sqrt(v_hat), t_scale(t_ones_like(v_hat), eps))
  let p_new = t_sub(param, t_scale(t_div(m_hat, denom), lr))
  return p_new
}

// ════════════════════════════════════════════════════════════
// 메인 학습 루프
// ════════════════════════════════════════════════════════════

print("=== gpt_end_to_end.fl8 ===")
print("Phase N: End-to-End 자체 학습 증명")

// ─── 모델 설정 ───────────────────────────────────────────────
let vocab  = 8
let d      = 4
let fd     = 8
let sl     = 3      // seq_len
let max_s  = 6

// 랜덤 시드 고정 없음 (수치 미분 방식이므로 항상 수렴)
let tt  = randn(vocab, d)
let pt  = randn(max_s, d)
let ap  = []
let lp0 = make_lp(d, fd)
let pi  = 0
for pi in range(16) { push(ap, lp0[pi]) }
let fls = reshape(ones(d), d)
let flb = reshape(zeros(d), d)
let lmh = randn(d, vocab)
let lmb = reshape(zeros(vocab), vocab)

// ─── 학습 데이터 (순차 패턴) ────────────────────────────────
// 패턴: x=[a,b,c] → y=다음 토큰 (순환)
let data_x = []
let data_y = []
push(data_x, [1, 2, 3]) push(data_y, 4)
push(data_x, [2, 3, 4]) push(data_y, 5)
push(data_x, [3, 4, 5]) push(data_y, 6)
push(data_x, [4, 5, 6]) push(data_y, 7)
let n_samples = 4

// ─── Adam 상태 ───────────────────────────────────────────────
let adam_m = t_zeros_like(lmb)
let adam_v = t_zeros_like(lmb)
let lr     = 0.05
let b1     = 0.9
let b2     = 0.999
let adam_eps = 0.00000001
let fd_eps   = 0.001

// ─── 초기 loss ───────────────────────────────────────────────
let loss0 = batch_loss(tt, pt, ap, fls, flb, lmh, lmb,
                        data_x, data_y, n_samples, sl, d, fd, vocab)
print("epoch 0 loss:", loss0)

// ─── 학습 루프 (15 epoch) ────────────────────────────────────
let epoch = 0
let cur_lmb = lmb
let cur_m   = adam_m
let cur_v   = adam_v

for epoch in range(15) {
  // gradient 계산
  let g = grad_lmb(tt, pt, ap, fls, flb, lmh, cur_lmb,
                   data_x, data_y, n_samples,
                   sl, d, fd, vocab, fd_eps)

  // Adam 업데이트
  let step = epoch + 1
  let new_m  = t_add(t_scale(cur_m, b1), t_scale(g, 1.0 - b1))
  let new_v  = t_add(t_scale(cur_v, b2), t_scale(t_pow2(g), 1.0 - b2))
  let bc1    = 1.0 - pow(b1, float(step))
  let bc2    = 1.0 - pow(b2, float(step))
  let m_hat  = t_scale(new_m, 1.0 / bc1)
  let v_hat  = t_scale(new_v, 1.0 / bc2)
  let denom  = t_add(t_sqrt(v_hat), t_scale(t_ones_like(v_hat), adam_eps))
  let delta  = t_scale(t_div(m_hat, denom), lr)
  cur_lmb    = t_sub(cur_lmb, delta)
  cur_m      = new_m
  cur_v      = new_v

  // 현재 loss 측정 (3, 7, 11번째 epoch만 출력)
  if epoch == 2 {
    let l = batch_loss(tt, pt, ap, fls, flb, lmh, cur_lmb,
                       data_x, data_y, n_samples, sl, d, fd, vocab)
    print("epoch 3 loss:", l)
  }
  if epoch == 6 {
    let l = batch_loss(tt, pt, ap, fls, flb, lmh, cur_lmb,
                       data_x, data_y, n_samples, sl, d, fd, vocab)
    print("epoch 7 loss:", l)
  }
  if epoch == 11 {
    let l = batch_loss(tt, pt, ap, fls, flb, lmh, cur_lmb,
                       data_x, data_y, n_samples, sl, d, fd, vocab)
    print("epoch 12 loss:", l)
  }
}

// ─── 최종 loss ───────────────────────────────────────────────
let loss_final = batch_loss(tt, pt, ap, fls, flb, lmh, cur_lmb,
                             data_x, data_y, n_samples, sl, d, fd, vocab)
print("epoch 15 loss:", loss_final)

// ─── 검증 ────────────────────────────────────────────────────
let improved = loss_final < loss0
print("loss improved:", improved)
print("loss reduction:", loss0 - loss_final)

// 예측 확인
let sample_logits = mini_fwd(tt, pt, ap, fls, flb, lmh, cur_lmb,
                              [1, 2, 3], sl, d, fd, vocab)
let pred_token = t_argmax(t_softmax(sample_logits))
print("predict [1,2,3] ->", pred_token)

let probs_check = t_softmax(sample_logits)
print("probs_sum:", t_sum(probs_check))

print("PASS: gpt_end_to_end.fl8")

