test("Adam 1-step → loss 감소 (작은 모델)", () => {
  const r = runFL8(`
let vocab = 6
let d = 4
let tok_t = randn(vocab, d)
let pos_t = randn(3, d)
let lmh   = randn(d, vocab)
let lmb   = reshape(zeros(vocab), vocab)

fn simple_fwd(tt: i32, pt: i32, lmh: i32, lmb: i32, ids: i32, d: i32, vocab: i32) -> i32 {
  let te = zeros(3, d)
  let i = 0
  for i in range(3) { t_set_row(te, i, t_row(tt, int(ids[i]))) }
  let pe = zeros(3, d)
  for i in range(3) { t_set_row(pe, i, t_row(pt, i)) }
  let x    = t_add(te, pe)
  let last = t_row(x, 2)
  let fls  = reshape(ones(d), d)
  let flb  = reshape(zeros(d), d)
  let ln   = t_layer_norm(last, fls, flb, 0.00001)
  let logits = t_row(matmul(reshape(ln, 1, d), lmh), 0)
  return t_add(logits, lmb)
}

let target = 4
let ids    = [1, 2, 3]
let loss0  = t_ce_loss(simple_fwd(tok_t, pos_t, lmh, lmb, ids, d, vocab), target)

// lm_bias에 대해 수치 미분 + Adam 1 step
let eps = 0.001
let grad = reshape(zeros(vocab), vocab)
let k = 0
for k in range(vocab) {
  let lp = t_copy(lmb)
  t_set(lp, k, t_get(lp, k) + eps)
  let llp = t_ce_loss(simple_fwd(tok_t, pos_t, lmh, lp, ids, d, vocab), target)
  let lm = t_copy(lmb)
  t_set(lm, k, t_get(lm, k) - eps)
  let llm = t_ce_loss(simple_fwd(tok_t, pos_t, lmh, lm, ids, d, vocab), target)
  t_set(grad, k, (llp - llm) / (2.0 * eps))
}

let lr  = 0.1
let b1  = 0.9
let b2  = 0.999
let ae  = 0.00000001
let m_  = t_zeros_like(lmb)
let v_  = t_zeros_like(lmb)
let mn  = t_add(t_scale(m_, b1), t_scale(grad, 1.0 - b1))
let vn  = t_add(t_scale(v_, b2), t_scale(t_pow2(grad), 1.0 - b2))
let mh  = t_scale(mn, 1.0 / (1.0 - pow(b1, 1.0)))
let vh  = t_scale(vn, 1.0 / (1.0 - pow(b2, 1.0)))
let den = t_add(t_sqrt(vh), t_scale(t_ones_like(vh), ae))
let lmb1 = t_sub(lmb, t_scale(t_div(mh, den), lr))

let loss1 = t_ce_loss(simple_fwd(tok_t, pos_t, lmh, lmb1, ids, d, vocab), target)
loss0 - loss1
`);
  expectGt(r.val, 0, "loss decreased after adam step");
});

test("3 epoch 학습 → loss 단조 감소 경향", () => {
  const r = runFL8(`
let vocab = 5
let lmb   = reshape(zeros(vocab), vocab)
let target = 2
let lr = 0.1
let b1 = 0.9
let b2 = 0.999
let eps_fd = 0.001
let ae  = 0.00000001

fn get_loss(lmb: i32, target: i32) -> i32 {
  return t_ce_loss(lmb, target)
}

fn get_grad(lmb: i32, target: i32, eps: i32, vocab: i32) -> i32 {
  let g = t_zeros_like(lmb)
  let k = 0
  for k in range(vocab) {
    let lp = t_copy(lmb)
    t_set(lp, k, t_get(lp, k) + eps)
    let lm_ = t_copy(lmb)
    t_set(lm_, k, t_get(lm_, k) - eps)
    t_set(g, k, (get_loss(lp, target) - get_loss(lm_, target)) / (2.0 * eps))
  }
  return g
}

let m_ = t_zeros_like(lmb)
let v_ = t_zeros_like(lmb)
let loss0 = get_loss(lmb, target)

let cur = lmb
let cm  = m_
let cv  = v_

let ep = 0
for ep in range(3) {
  let g = get_grad(cur, target, eps_fd, vocab)
  let s = ep + 1
  let mn = t_add(t_scale(cm, b1), t_scale(g, 1.0 - b1))
  let vn = t_add(t_scale(cv, b2), t_scale(t_pow2(g), 1.0 - b2))
  let mh = t_scale(mn, 1.0 / (1.0 - pow(b1, float(s))))
  let vh = t_scale(vn, 1.0 / (1.0 - pow(b2, float(s))))
  let den = t_add(t_sqrt(vh), t_scale(t_ones_like(vh), ae))
  cur = t_sub(cur, t_scale(t_div(mh, den), lr))
  cm = mn
  cv = vn
}
let loss3 = get_loss(cur, target)
loss0 - loss3
`);
  expectGt(r.val, 0, "3-epoch loss decreased");
});

