// FreeLang v8 ML — Phase O: 전체 파라미터 학습
//
// Phase N 개선:
//   - vocab=16, d=8, ffn=16, layers=2, seq=4
//   - lm_head + lm_bias 동시 학습 (수치 미분)
//   - 8개 학습 샘플 (순차 + 역방향 패턴)
//   - 50 epoch, 매 epoch loss 출력
//   - 최종 정확도(accuracy) 측정
//
// ── 인라인 의존 함수 ─────────────────────────────────────────

fn embed_seq(table: i32, ids: i32, sl: i32, d: i32) -> i32 {
  let out = zeros(sl, d)
  let i = 0
  for i in range(sl) {
    t_set_row(out, i, t_row(table, int(ids[i])))
  }
  return out
}

fn embed_fwd(tt: i32, pt: i32, ids: i32, sl: i32, d: i32) -> i32 {
  let te = embed_seq(tt, ids, sl, d)
  let pe = zeros(sl, d)
  let i = 0
  for i in range(sl) { t_set_row(pe, i, t_row(pt, i)) }
  return t_add(te, pe)
}

fn linear_fwd(x: i32, W: i32, b: i32, sl: i32, od: i32) -> i32 {
  let out = matmul(x, W)
  let i = 0
  for i in range(sl) { t_set_row(out, i, t_add(t_row(out, i), b)) }
  return out
}

fn row_sm(t: i32, r: i32, c: i32) -> i32 {
  let out = zeros(r, c)
  let i = 0
  for i in range(r) { t_set_row(out, i, t_softmax(t_row(t, i))) }
  return out
}

fn attn_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
            bq: i32, bk: i32, bv: i32, bo: i32, sl: i32, d: i32) -> i32 {
  let Q = linear_fwd(x, Wq, bq, sl, d)
  let K = linear_fwd(x, Wk, bk, sl, d)
  let V = linear_fwd(x, Wv, bv, sl, d)
  let sm2 = t_add(t_scale(matmul(Q, transpose(K)), 1.0/sqrt(float(d))),
                  t_causal_mask(sl))
  return linear_fwd(matmul(row_sm(sm2, sl, sl), V), Wo, bo, sl, d)
}

fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32, sl: i32, d: i32, fd: i32) -> i32 {
  let h = matmul(x, W1)
  let i = 0
  for i in range(sl) { t_set_row(h, i, t_add(t_row(h, i), b1)) }
  let out = matmul(t_gelu(h), W2)
  for i in range(sl) { t_set_row(out, i, t_add(t_row(out, i), b2)) }
  return out
}

fn row_ln(x: i32, sc: i32, bi: i32, sl: i32, d: i32) -> i32 {
  let out = zeros(sl, d)
  let i = 0
  for i in range(sl) { t_set_row(out, i, t_layer_norm(t_row(x, i), sc, bi, 0.00001)) }
  return out
}

fn block_fwd(x: i32, Wq: i32, Wk: i32, Wv: i32, Wo: i32,
             bq: i32, bk: i32, bv: i32, bo: i32,
             W1: i32, b1: i32, W2: i32, b2: i32,
             ln1s: i32, ln1b: i32, ln2s: i32, ln2b: i32,
             sl: i32, d: i32, fd: i32) -> i32 {
  let x1 = row_ln(x, ln1s, ln1b, sl, d)
  let x2 = t_add(x, attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, sl, d))
  return t_add(x2, ffn_fwd(row_ln(x2, ln2s, ln2b, sl, d), W1, b1, W2, b2, sl, d, fd))
}

fn layer_fwd(x: i32, p: i32, li: i32, sl: i32, d: i32, fd: i32) -> i32 {
  let base = li * 16
  return block_fwd(x,
    p[base+0], p[base+1], p[base+2], p[base+3],
    p[base+4], p[base+5], p[base+6], p[base+7],
    p[base+8], p[base+9], p[base+10], p[base+11],
    p[base+12], p[base+13], p[base+14], p[base+15],
    sl, d, fd)
}

fn make_lp(d: i32, fd: i32) -> i32 {
  let p = []
  push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d)) push(p, randn(d, d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, reshape(zeros(d), d)) push(p, reshape(zeros(d), d))
  push(p, randn(d, fd)) push(p, reshape(zeros(fd), fd))
  push(p, randn(fd, d)) push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d))  push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d))  push(p, reshape(zeros(d), d))
  return p
}

// ─── forward: 고정 파라미터 + 학습 대상 lmh, lmb ────────────
fn fwd(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32, nl: i32,
       lmh: i32, lmb: i32, ids: i32, sl: i32, d: i32, fd: i32, vocab: i32) -> i32 {
  let x = embed_fwd(tt, pt, ids, sl, d)
  let li = 0
  for li in range(nl) { x = layer_fwd(x, ap, li, sl, d, fd) }
  let ln_out = t_layer_norm(t_row(x, sl - 1), fls, flb, 0.00001)
  let logits  = t_row(matmul(reshape(ln_out, 1, d), lmh), 0)
  return t_add(logits, lmb)
}

// ─── batch loss ──────────────────────────────────────────────
fn bloss(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32, nl: i32,
         lmh: i32, lmb: i32, dx: i32, dy: i32, ns: i32,
         sl: i32, d: i32, fd: i32, vocab: i32) -> i32 {
  let tot = 0.0
  let i = 0
  for i in range(ns) {
    tot = tot + t_ce_loss(fwd(tt, pt, ap, fls, flb, nl,
                              lmh, lmb, dx[i], sl, d, fd, vocab),
                          int(dy[i]))
  }
  return tot / float(ns)
}

// ─── lmb 수치 미분 ───────────────────────────────────────────
fn grad_b(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32, nl: i32,
          lmh: i32, lmb: i32, dx: i32, dy: i32, ns: i32,
          sl: i32, d: i32, fd: i32, vocab: i32, eps: i32) -> i32 {
  let g = t_zeros_like(lmb)
  let k = 0
  for k in range(vocab) {
    let lp = t_copy(lmb)
    t_set(lp, k, t_get(lp, k) + eps)
    let lm = t_copy(lmb)
    t_set(lm, k, t_get(lm, k) - eps)
    let gv = (bloss(tt, pt, ap, fls, flb, nl, lmh, lp, dx, dy, ns, sl, d, fd, vocab) -
              bloss(tt, pt, ap, fls, flb, nl, lmh, lm, dx, dy, ns, sl, d, fd, vocab)) / (2.0 * eps)
    t_set(g, k, gv)
  }
  return g
}

// ─── lmh 수치 미분 (열 단위) ─────────────────────────────────
// lmh: [d, vocab] 행렬 → t_flatten으로 1D 취급 후 각 원소 미분
fn grad_h(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32, nl: i32,
          lmh: i32, lmb: i32, dx: i32, dy: i32, ns: i32,
          sl: i32, d: i32, fd: i32, vocab: i32, eps: i32) -> i32 {
  let flat_g = reshape(zeros(d * vocab), d, vocab)
  let ri = 0
  for ri in range(d) {
    let ci = 0
    for ci in range(vocab) {
      let lmh_p = t_copy(lmh)
      let v_p = tget(lmh_p, ri, ci) + eps
      tset(lmh_p, ri, ci, v_p)
      let lmh_m = t_copy(lmh)
      let v_m = tget(lmh_m, ri, ci) - eps
      tset(lmh_m, ri, ci, v_m)
      let gv = (bloss(tt, pt, ap, fls, flb, nl, lmh_p, lmb, dx, dy, ns, sl, d, fd, vocab) -
                bloss(tt, pt, ap, fls, flb, nl, lmh_m, lmb, dx, dy, ns, sl, d, fd, vocab)) / (2.0 * eps)
      tset(flat_g, ri, ci, gv)
    }
  }
  return flat_g
}

// ─── Adam 상태 ───────────────────────────────────────────────
fn adam_step1d(param: i32, g: i32, m: i32, v: i32, step: i32,
               lr: i32, b1: i32, b2: i32, ae: i32) -> i32 {
  let mn = t_add(t_scale(m, b1), t_scale(g, 1.0 - b1))
  let vn = t_add(t_scale(v, b2), t_scale(t_pow2(g), 1.0 - b2))
  let mh = t_scale(mn, 1.0 / (1.0 - pow(b1, float(step))))
  let vh = t_scale(vn, 1.0 / (1.0 - pow(b2, float(step))))
  let den = t_add(t_sqrt(vh), t_scale(t_ones_like(vh), ae))
  let p2 = t_sub(param, t_scale(t_div(mh, den), lr))
  return p2
}

fn adam_step2d(param: i32, g: i32, m: i32, v: i32, step: i32,
               lr: i32, b1: i32, b2: i32, ae: i32) -> i32 {
  // 2D 텐서도 elementwise 동일
  let mn = t_add(t_scale(m, b1), t_scale(g, 1.0 - b1))
  let vn = t_add(t_scale(v, b2), t_scale(t_pow2(g), 1.0 - b2))
  let mh = t_scale(mn, 1.0 / (1.0 - pow(b1, float(step))))
  let vh = t_scale(vn, 1.0 / (1.0 - pow(b2, float(step))))
  let den = t_add(t_sqrt(vh), t_scale(t_ones_like(vh), ae))
  return t_sub(param, t_scale(t_div(mh, den), lr))
}

// ════════════════════════════════════════════════════════════
// 학습 설정
// ════════════════════════════════════════════════════════════

