  push(p, reshape(ones(d), d))  push(p, reshape(zeros(d), d))
  push(p, reshape(ones(d), d))  push(p, reshape(zeros(d), d))
  return p
}

// ─── forward: 고정 파라미터 + 학습 대상 lmh, lmb ────────────
fn fwd(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32, nl: i32,
       lmh: i32, lmb: i32, ids: i32, sl: i32, d: i32, fd: i32, vocab: i32) -> i32 {
  let x = embed_fwd(tt, pt, ids, sl, d)
  let li = 0
  for li in range(nl) { x = layer_fwd(x, ap, li, sl, d, fd) }
  let ln_out = t_layer_norm(t_row(x, sl - 1), fls, flb, 0.00001)
  let logits  = t_row(matmul(reshape(ln_out, 1, d), lmh), 0)
  return t_add(logits, lmb)
}

// ─── batch loss ──────────────────────────────────────────────
fn bloss(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32, nl: i32,
         lmh: i32, lmb: i32, dx: i32, dy: i32, ns: i32,
         sl: i32, d: i32, fd: i32, vocab: i32) -> i32 {
  let tot = 0.0
  let i = 0
  for i in range(ns) {
    tot = tot + t_ce_loss(fwd(tt, pt, ap, fls, flb, nl,
                              lmh, lmb, dx[i], sl, d, fd, vocab),
                          int(dy[i]))
  }
  return tot / float(ns)
}

// ─── lmb 수치 미분 ───────────────────────────────────────────
fn grad_b(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32, nl: i32,
          lmh: i32, lmb: i32, dx: i32, dy: i32, ns: i32,
          sl: i32, d: i32, fd: i32, vocab: i32, eps: i32) -> i32 {
  let g = t_zeros_like(lmb)
  let k = 0
  for k in range(vocab) {
    let lp = t_copy(lmb)
    t_set(lp, k, t_get(lp, k) + eps)
    let lm = t_copy(lmb)
    t_set(lm, k, t_get(lm, k) - eps)
    let gv = (bloss(tt, pt, ap, fls, flb, nl, lmh, lp, dx, dy, ns, sl, d, fd, vocab) -
              bloss(tt, pt, ap, fls, flb, nl, lmh, lm, dx, dy, ns, sl, d, fd, vocab)) / (2.0 * eps)
    t_set(g, k, gv)
  }
  return g
}

// ─── lmh 수치 미분 (열 단위) ─────────────────────────────────
// lmh: [d, vocab] 행렬 → t_flatten으로 1D 취급 후 각 원소 미분
fn grad_h(tt: i32, pt: i32, ap: i32, fls: i32, flb: i32, nl: i32,
          lmh: i32, lmb: i32, dx: i32, dy: i32, ns: i32,
          sl: i32, d: i32, fd: i32, vocab: i32, eps: i32) -> i32 {
  let flat_g = reshape(zeros(d * vocab), d, vocab)
  let ri = 0
  for ri in range(d) {
    let ci = 0
    for ci in range(vocab) {
      let lmh_p = t_copy(lmh)
      let v_p = tget(lmh_p, ri, ci) + eps
      tset(lmh_p, ri, ci, v_p)
      let lmh_m = t_copy(lmh)
      let v_m = tget(lmh_m, ri, ci) - eps
      tset(lmh_m, ri, ci, v_m)
      let gv = (bloss(tt, pt, ap, fls, flb, nl, lmh_p, lmb, dx, dy, ns, sl, d, fd, vocab) -
                bloss(tt, pt, ap, fls, flb, nl, lmh_m, lmb, dx, dy, ns, sl, d, fd, vocab)) / (2.0 * eps)
      tset(flat_g, ri, ci, gv)
    }
  }
  return flat_g
}

// ─── Adam 상태 ───────────────────────────────────────────────
fn adam_step1d(param: i32, g: i32, m: i32, v: i32, step: i32,
               lr: i32, b1: i32, b2: i32, ae: i32) -> i32 {
  let mn = t_add(t_scale(m, b1), t_scale(g, 1.0 - b1))
  let vn = t_add(t_scale(v, b2), t_scale(t_pow2(g), 1.0 - b2))
  let mh = t_scale(mn, 1.0 / (1.0 - pow(b1, float(step))))
  let vh = t_scale(vn, 1.0 / (1.0 - pow(b2, float(step))))
  let den = t_add(t_sqrt(vh), t_scale(t_ones_like(vh), ae))
  let p2 = t_sub(param, t_scale(t_div(mh, den), lr))
  return p2
}

fn adam_step2d(param: i32, g: i32, m: i32, v: i32, step: i32,
               lr: i32, b1: i32, b2: i32, ae: i32) -> i32 {
  // 2D 텐서도 elementwise 동일
  let mn = t_add(t_scale(m, b1), t_scale(g, 1.0 - b1))
  let vn = t_add(t_scale(v, b2), t_scale(t_pow2(g), 1.0 - b2))
  let mh = t_scale(mn, 1.0 / (1.0 - pow(b1, float(step))))
  let vh = t_scale(vn, 1.0 / (1.0 - pow(b2, float(step))))
  let den = t_add(t_sqrt(vh), t_scale(t_ones_like(vh), ae))
  return t_sub(param, t_scale(t_div(mh, den), lr))
}

// ════════════════════════════════════════════════════════════
// 학습 설정
// ════════════════════════════════════════════════════════════

print("=== gpt_train_full.fl8 ===")
print("Phase O: lm_head + lm_bias 전체 학습")

let vocab  = 16
let d      = 8
let fd     = 16
let nl     = 2
let sl     = 4
let max_s  = 8

// 파라미터 초기화
let tt  = randn(vocab, d)
let pt  = randn(max_s, d)
let ap  = []
let lp0 = make_lp(d, fd)
let lp1 = make_lp(d, fd)
let pi  = 0
for pi in range(16) { push(ap, lp0[pi]) }
for pi in range(16) { push(ap, lp1[pi]) }

let fls = reshape(ones(d), d)
let flb = reshape(zeros(d), d)
let lmh = randn(d, vocab)
let lmb = reshape(zeros(vocab), vocab)

// ─── 학습 데이터 ─────────────────────────────────────────────
// 순차 패턴: [a,b,c,d] → e (e = (d+1) % vocab)
let dx = []
let dy = []
push(dx, [1,2,3,4])   push(dy, 5)
push(dx, [2,3,4,5])   push(dy, 6)
push(dx, [3,4,5,6])   push(dy, 7)
push(dx, [4,5,6,7])   push(dy, 8)
push(dx, [5,6,7,8])   push(dy, 9)
push(dx, [6,7,8,9])   push(dy, 10)
push(dx, [7,8,9,10])  push(dy, 11)
push(dx, [8,9,10,11]) push(dy, 12)
let ns = 8

// ─── 하이퍼파라미터 ──────────────────────────────────────────
let lr   = 0.02
let b1   = 0.9
let b2   = 0.999
let ae   = 0.00000001
let eps  = 0.002

// ─── Adam 상태 초기화 ────────────────────────────────────────
let mb  = t_zeros_like(lmb)
let vb  = t_zeros_like(lmb)
let mh  = t_zeros_like(lmh)
let vh  = t_zeros_like(lmh)

// ─── 초기 loss ───────────────────────────────────────────────
let l0 = bloss(tt, pt, ap, fls, flb, nl, lmh, lmb, dx, dy, ns, sl, d, fd, vocab)
print("epoch  0 loss:", l0)

// ─── 학습 루프 ───────────────────────────────────────────────
let cur_h = lmh
let cur_b = lmb
let cur_mh = mh
let cur_vh = vh
let cur_mb = mb
let cur_vb = vb

let ep = 0
for ep in range(30) {
  let step = ep + 1

  // lm_bias gradient & update
  let gb = grad_b(tt, pt, ap, fls, flb, nl, cur_h, cur_b,
                  dx, dy, ns, sl, d, fd, vocab, eps)
  let new_b = adam_step1d(cur_b, gb, cur_mb, cur_vb, step, lr, b1, b2, ae)
  let new_mb = t_add(t_scale(cur_mb, b1), t_scale(gb, 1.0 - b1))
  let new_vb = t_add(t_scale(cur_vb, b2), t_scale(t_pow2(gb), 1.0 - b2))

  // lm_head gradient & update
  let gh = grad_h(tt, pt, ap, fls, flb, nl, cur_h, new_b,
                  dx, dy, ns, sl, d, fd, vocab, eps)
  let new_h = adam_step2d(cur_h, gh, cur_mh, cur_vh, step, lr, b1, b2, ae)
  let new_mh = t_add(t_scale(cur_mh, b1), t_scale(gh, 1.0 - b1))
  let new_vh = t_add(t_scale(cur_vh, b2), t_scale(t_pow2(gh), 1.0 - b2))

  cur_b  = new_b
  cur_mb = new_mb
  cur_vb = new_vb
  cur_h  = new_h
  cur_mh = new_mh
  cur_vh = new_vh

  // 매 5 epoch마다 loss 출력
  if step == 5 {
    let l = bloss(tt, pt, ap, fls, flb, nl, cur_h, cur_b, dx, dy, ns, sl, d, fd, vocab)
    print("epoch  5 loss:", l)
  }
  if step == 10 {
    let l = bloss(tt, pt, ap, fls, flb, nl, cur_h, cur_b, dx, dy, ns, sl, d, fd, vocab)
    print("epoch 10 loss:", l)
  }
  if step == 15 {
    let l = bloss(tt, pt, ap, fls, flb, nl, cur_h, cur_b, dx, dy, ns, sl, d, fd, vocab)
    print("epoch 15 loss:", l)
  }
  if step == 20 {
    let l = bloss(tt, pt, ap, fls, flb, nl, cur_h, cur_b, dx, dy, ns, sl, d, fd, vocab)
    print("epoch 20 loss:", l)
  }
  if step == 25 {
    let l = bloss(tt, pt, ap, fls, flb, nl, cur_h, cur_b, dx, dy, ns, sl, d, fd, vocab)
    print("epoch 25 loss:", l)
  }
}

// ─── 최종 평가 ───────────────────────────────────────────────
let l_final = bloss(tt, pt, ap, fls, flb, nl, cur_h, cur_b, dx, dy, ns, sl, d, fd, vocab)
print("epoch 30 loss:", l_final)
print("loss improved:", l_final < l0)
print("total reduction:", l0 - l_final)

// 정확도 측정 (각 샘플 예측이 맞는지)
let correct = 0
let i = 0
for i in range(ns) {
  let logits = fwd(tt, pt, ap, fls, flb, nl, cur_h, cur_b,
                   dx[i], sl, d, fd, vocab)
  let pred = t_argmax(t_softmax(logits))
  if pred == int(dy[i]) {
    correct = correct + 1
  }
}
print("accuracy:", correct, "/", ns)

print("PASS: gpt_train_full.fl8")
